          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"18eb8b2f-b5ce-511c-9cbd-c81c6588b264","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -زنا احملصن -احلدود تدرأ بالشبهات -التعزير بالسجن واجللد واإلبعاد .","document_number":"33438000","case_number":"33542626","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة وبن على املعاملة احملالة لنا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/25","year":"1434","subject":"زنا -زنا احملصن -احلدود تدرأ بالشبهات -التعزير بالسجن واجللد واإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33438000 :‬تاريخه‪1434/10/25 :‬هـ‬\n                    ‫رقم الدعوى‪33542626 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3422471‬تاريخه‪1434/1/25 :‬هـ‬\n\n\n ‫زنــا ‪ -‬زنــا احملصــن‪ -‬احلــدود تــدرأ بالشــبهات ‪ -‬التعزيــر بالســجن‬\n                                                   ‫واجللــد واإلبعــاد ‪.‬‬\n\n\n\n ‫‪ .1‬قــول النبــي صلــى اهلل عليــه وســلم ‪« :‬ادرؤوا احلــدود بالشــبهات مــا‬\n                                                                                                                              ‫اســتطعتم»‬\n  ‫‪ .2‬قــال ابــن قدامــة يف املغنــي ‪َ « : 353/9‬و َل َحـ َّـد ِف َو ْطءِ ال ِّنـ َـك ِ‬\n ‫اح‬\n   ‫اســدِ ‪َ ،‬س ـ َواء ًا اعْ َت َقـ َـدا ِح َّل ـ ُه َأ ْو ُح ْر َم َت ـ ُه ‪ ...‬ثــم قــال رحمــه اهلل ‪َّ :‬‬\n ‫«إن‬                                                                                                                                         ‫ا ْل َف ِ‬\n ‫اح ِب َغ ْيـ ِر ُشـ ُـهودٍ‪،‬‬    ‫كال ِّنـ َـك ِ‬   ‫الـ ُّـد‪َ ،‬‬ ‫اح ِتـهِ‪ ،‬فَ َلـ ْـم َي ِجـ ْـب ِبـ ِه ْ َ‬   ‫ـف ِف إ َب َ‬     ‫َهـ َـذا ُم ْخ َت َلـ ٌ‬\n ‫الشـ ُـب َهاتِ « إال أن‬           ‫الشـ ُـب َهاتِ ‪َ ،‬و ِال ْخ ِتـ َـا ُف فِ ي ـ ِه أ َْق ـ َوى ُّ‬       ‫ال َّــد ُيْــد َر ُأ ِب ُّ‬ ‫َو ِ َل َّن ْ َ‬\n ‫هــذا ال مينــع مــن تعزيرهــا علــى فعلهــا لعــدم إثباتهــا مــا دفعــت بــه مــن‬\n              ‫حصــول الــزواج‪ ،‬وقــد قــال ابــن قدامــه يف املغنــي ‪َ »353/9‬عـ ْـن َّ‬\n ‫الشـ ْـع ِب ِّي‬\n                                           ‫ـاب ال َّن ِبـ ِّـي َص َّلــى َّ ُ‬\n ‫الل َع َل ْي ـ ِه َو َس ـ َّل َم أ ََشـ َّـد‬                                     ‫ان أ ََحـ ٌـد مِ ـ ْـن أ َْص َحـ ِ‬ ‫ك َ‬     ‫َقــالَ ‪َ :‬مــا َ‬\n ‫ان َي ْض ـ ِر ُب فِ ي ـ ِه َو َر َوى‬        ‫ك َ‬                 ‫اح ِب َغ ْي ـ ِر َو ِلـ ٍّـي مِ ـ ْـن َع ِلـ ٍّـي َر ِضـ َـي َّ ُ‬\n                                                  ‫الل َع ْن ـ ُه َ‬                                                                 ‫ِف ال ِّ َنــك ِ‬\n ‫الط ِريـ َـق َج َم َعـ ْـت َر ْك ًبــا‬        ‫الشــا َل ْن ِج ُّي‪ِ ،‬ب ِإ ْسـ َنا ِد ِه َعـ ْـن عِ ْك ِر َمـ َة ْبـ ِـن َخا ِلــدٍ ‪ ،‬أ ََّن َّ‬  ‫َّ‬\n ‫اق‬  ‫فِ يـ ِه ْامـ َـر َأ ٌة َث ِّيـ ٌـب‪ ،‬فَ َخ َط َب َهــا َر ُجــلٌ ‪ ،‬فَ َأ ْن َك َح َهــا َر ُجــلٌ َو ُهـ َو َغ ْيـ ُـر َو ِلـ ٍّـي ِب َصـ َـد ٍ‬\n                                                         ‫َو ُشـ ُـهودٍ‪ ،‬فَ َل َّمــا َقدِ ُمــوا َع َلــى ُع َمـ َـر‪َ ،‬ر ِضـ َـي َّ ُ‬\n ‫الل َع ْن ـ ُه ُرفِ ـ َـع إ َل ْي ـ ِه أ َْم ُر ُه َمــا‪،‬‬\n                                                                  ‫اكـ َـح َو ْالُ ْنكِ ـ َـح‪.‬‬\n                                                                                           ‫فَ َفـ َّـر َق َب ْي َن ُه َمــا‪َ ،‬و َج َلـ َـد ال َّن ِ‬\n\n\n\n                                                                                                                                                         ‫‪222‬‬\n\f      ‫ادعــى املدعــي العــام علــى املدعــى عليهــا بقيامهــا بفعــل فاحشــة الزنــا‬\n      ‫ممــا نتــج عنــه حملهــا ســفاح ًا يطلــب إثبــات مــا أســند إليهــا ‪ ،‬واحلكــم‬\n      ‫عليهــا بحــد الزانــي احملصــن ‪ -‬حيــث إنــه ورد بــاغ للشــرطة مــن قبــل‬\n      ‫إدارة (املستشــفى) عــن دخــول املدعــى عليهــا للمستشــفى وهــي تعاني من‬\n      ‫حالــة (إجهــاض غيــر كامــل وتبــن وجــود حمــل متعفــن داخــل الرحــم)‪.‬‬\n      ‫ـخص يدعــى ‪ .....‬يســكن‬      ‫وباســتجوابها أقــرت أنهــا تزوجــت مــن شـ ٍ‬\n      ‫املدينــة املنــورة (فصلــت لــه أوراق مســتقلة) وال يوجــد ورقــة رســمية تثبــت‬\n      ‫ذلــك وكان زواجهــا منــه بغيــر علــم والدهــا وبغيــر شــهود وأنــه املتســبب‬\n      ‫الوحيــد يف حملهــا ‪ ،‬وأنــه كان يجامعهــا كمــا يجامــع الرجــل زوجتــه‪،‬‬\n      ‫زواج ســابق يف بلدهــا ولديهــا طفلــة مــن‬ ‫كمــا أقــرت أنهــا مطلقــة مــن ٍ‬\n      ‫زوجهــا الســابق ‪ .‬وقــد انتهــى التحقيــق إلــى اتهــام املدعــى عليهــا ‪.....‬‬\n      ‫بفعــل فاحشــة الزنــا ممــا نتــج عنــه حملهــا ســفاح ًا ‪ -‬أقــرت املدعــى عليهــا‬\n      ‫مبــا جــاء يف الدعــوى ولكــن دفعــت بــأن الفاعــل زوجهــا وقــد تزوجهــا‬\n      ‫بــدون ولــي وال شــهود وعقــد لهــم شــخص ووقعــت علــى ورقــة وليســت‬\n      ‫لديهــا وإمنــا عنــد زوجهــا وهــي مــا تــزال يف عصمتــه‪ ،‬بنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بعــد ثبــوت مــا يوجــب إقامــة حــد الزانــي احملصــن‬\n      ‫علــى املدعــى عليهــا ورد دعــوى املدعــي العــام طلبــه ذلــك وبتعزيــر املدعــى‬\n      ‫عليهــا للشــبهة وذلــك بســجنها ســنة ابتــداء مــن تاريــخ إيقافهــا علــى ذمــة‬\n      ‫القضيــة وجلدهــا مائتــي جلــدة مفرقــة علــى دفعتــن متســاويتني بــن‬\n      ‫الدفعتــن مــدة ال تقــل عــن خمســة عشــر يومــا والتوصيــة بإبعادهــا عــن‬\n      ‫البــاد بعــد انتهــاء محكوميتهــا‪ .‬قــرر املدعــي العــام عــدم القناعة وطلب‬\n\n‫‪223‬‬\n\f‫وتصديــق احلكــم‬\n             ‫االســتئناف بالئحــة وقــررت املدعــى عليهــا القناعــة‪ُ ،‬‬\n                                           ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدينــا‬\n‫ـاء‬\n ‫نحــن ‪ ...‬و‪ ....‬و‪ ....‬القضــاة يف احملكمــة العامــة مبكــة املكرمــة وبنـ ً‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n‫املكرمــة برقــم ‪ 33542626‬يف ‪1433/8/24‬ه ـ واملقيــدة يف احملكمــة‬\n‫برقــم ‪ 331588705‬يف ‪1433/8/24‬ه ـ ففــي يــوم األحــد ‪1433/9/3‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثانيــة بعــد الظهــر وفيهــا حضــر املدعــي العــام‬\n‫‪ ....‬وحضــر حلضــوره املدعــى عليهــا ‪ ....‬إندونيســية اجلنســية مبوجــب‬\n‫ا يف دعــواه ‪:‬‬  ‫البطاقــة البديلــة رقــم (‪ )...‬فادعــى املدعــي العــام قائ ـ ً‬\n‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة مبنطقــة مكــة‬\n‫املكرمــة أدعــي علــى املذكــورة أعاله حيث إنه بتاريــخ ‪1433/6/17‬هـ‬\n‫تبلــغ مركــز شــرطة التنعيــم مــن قبــل إدارة (‪ ).............‬عــن دخول املدعى‬\n‫عليهــا للمستشــفى وهــي تعانــي مــن حالــة (إجهــاض غيــر كامــل وتبــن‬\n‫وجــود حمــل متعفــن داخــل الرحم)‪.‬وباســتجوابها أقــرت أنهــا تزوجــت مــن‬\n‫ـخص يدعــى‪ ... /‬يســكن املدينــة املنــورة (فصلــت لــه أوراق مســتقلة)‬     ‫شـ ٍ‬\n‫وال يوجــد ورقــة رســمية تثبــت ذلــك وكان زواجهــا منــه بغيــر علــم والدها‬\n‫وبغيــر شــهود وأنــه املتســبب الوحيــد يف حملهــا ‪ ،‬وأنــه كان يجامعهــا‬\n‫زواج ســابق‬\n         ‫كمــا يجامــع الرجــل زوجتــه ‪ ،‬كمــا أقــرت أنهــا مطلقــة مــن ٍ‬\n‫يف بلدهــا ولديهــا طفلــة مــن زوجهــا الســابق ‪ .‬وقــد انتهــى التحقيــق إلــى‬\n‫اتهــام املدعــى عليهــا ‪ ...... /‬بفعــل فاحشــة الزنــا ممــا نتــج عنــه حملهــا‬\n\n                                                                                     ‫‪224‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":222,"source_page_end":224,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0f3837429642f4a2f85a4593e85c90b9aabffaf4e6150c82f3b80d2e1ecef4e0","normalized_text_hash":"baae67cb622adf658816e09366a3c1d998c911faa06f5a7935d4536bcec6bf8c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p222-33438000"},{"id":"0e4a7f9c-4106-518d-a6e8-4181cc2a15ac","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -زنا غير محصن -حد زنا غير احملصن -الرجوع عن اإلقرار بالزنا -الرجوع عن احلكم بحد زنا غير احملصن -إقامة عالقة محرمة برجل أجنبي -تعزير بالسجن واجللد وأخذ التعهد - االدعاء باحلق اخلاص.","document_number":"33446401","case_number":"33620566","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر مبوجب قرار معالي رئيس املجلس األعلى للقضاء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/3","year":"1434","subject":"زنا -زنا غير محصن -حد زنا غير احملصن -الرجوع عن اإلقرار بالزنا -الرجوع عن احلكم بحد زنا غير احملصن -إقامة عالقة محرمة برجل أجنبي -تعزير بالسجن واجللد وأخذ التعهد - االدعاء باحلق اخلاص.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33446401 :‬تاريخه‪1434/11/3:‬هـ‬\n                  ‫رقم الدعوى‪33620566 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34233656‬تاريخه‪1434/6/7 :‬هـ‬\n\n\n‫زنــا ‪ -‬زنــا غيــر محصــن‪ -‬حــد زنــا غيــر احملصــن‪ -‬الرجــوع عــن اإلقــرار‬\n‫بالزنــا ‪ -‬الرجــوع عــن احلكــم بحــد زنــا غيــر احملصــن ‪ -‬إقامــة عالقــة‬\n‫محرمــة برجــل أجنبــي‪ -‬تعزيــر بالســجن واجللــد وأخــذ التعهــد ‪-‬‬\n                                                  ‫االدعــاء باحلــق اخلــاص‪.‬‬\n\n\n\n\n    ‫‪ .1‬قول اهلل تعالى‪(:‬وال تقربوا الزنا إنه كان فاحشة وساء سبيال)‪.‬‬\n‫‪ .2‬قــول اهلل تعالــى (الزانيــة والزانــي فاجلــدوا كل واحــد منهمــا مائــة‬\n‫جلــدة وال تأخذكــم بهمــا رأفــة يف ديــن اهلل إن كنتــم تؤمنــون بــاهلل‬\n                 ‫واليــوم اآلخــر وليشــهد عذابهمــا طائفــة مــن املؤمنــن)‪.‬‬\n      ‫‪ .3‬قوله تعالى‪(:‬يا أيها الذين آمنوا ال تتبعوا خطوات الشيطان)‪.‬‬\n‫‪ .4‬قــول النبــي صلــى اهلل عليــه وســلم‪(:‬ما خلــى رجــل بامــرأة إال كان‬\n                                                          ‫الشــيطان ثالثهمــا)‪،‬‬\n‫‪ .5‬قــول النبــي صلــى اهلل عليــه وســلم‪ (:‬البكــر بالبكــر جلــد مائــة ونفــي‬\n                                                              ‫ســنة) رواه مســلم‪.‬‬\n‫‪ .6‬قــرار مجلــس القضــاء األعلــى رقــم ‪ 311/45‬وتاريخ‪1418/6/18‬ه ـ‬\n‫القاضــي بــأن علــى القضــاة إذا نظــروا يف قضيــة زنــا البكــر وثبــت موجب‬\n‫احلــد أن يحكمــوا بحــد زنــا البكــر وهــو اجللــد والتغريــب ويتــرك مــكان‬\n                        ‫التغريــب وكيفيتــه للجهــات املعنيــة بذلــك ‪.‬أ‪.‬ه ـ‬\n\n\n                                                                                    ‫‪228‬‬\n\f      ‫إدعــى املدعــى العــام علــى املدعــى عليــه (غيــر محصــن) بالتســبب يف‬\n      ‫هــروب وإخفــاء فتــاة وتغييبهــا عــن ذويهــا لفتــرة طويلــة والدخــول إلــى‬\n      ‫منزلهــا لغــرض االعتــداء علــى العــرض وفعــل فاحشــة الزنــا بالفتــاة‬\n      ‫وإقامــة عالقــة محرمــة معهــا والتغريــر بهــا وتوجيــه االتهــام للمدعــى‬\n      ‫عليهــا (غيــر محصنــة) بالهــروب والتغيــب عــن منــزل ذويهــا وإقامــة‬\n      ‫عالقــات محرمــة مــع شــخص أجنبــي عنهــا وممارســة فاحشــة الزنــا‬\n      ‫معــه وطلــب املدعــي العــام احلكــم عليهمــا بحــد الزانــي غيــر احملصــن‪،‬‬\n      ‫وبعقوبــة تعزيريــة لقــاء بقيــة مــا أســند إليهمــا ‪،‬بعــرض دعــوى املدعــي‬\n      ‫العــام علــى املدعــى عليــه صــادق عليــه جملــة وتفصيــا‪ ،‬وبعرضهــا علــى‬\n      ‫املدعــى عليهــا أنكــرت هروبهــا مــن منــزل أهلهــا ودفعــت أنهــا ذهبــت‬\n      ‫وهــي يف غيــر وعيهــا وال تــدرك مــا ُفعــل بهــا طيلــة املــدة‪ ،‬وقــررت توبتهــا‬\n      ‫وندمهــا‪ ،‬مبــا أن املدعــى عليــه أقــر مبــا جــاء يف دعــوى املدعــي العــام‬\n      ‫جملــة وتفصيـاً‪ ،‬وألنــه قــد توافــرت يف املدعــى عليــه شــروط حــد الزنــا‬\n      ‫وانتفــت عنــه موانعــه‪ ،‬وألنــه غيــر محصــن‪ ،‬ومبــا أن املدعــى عليهــا‬\n      ‫أقــرت بخروجهــا مــع رجــل ال متــت لــه بصلــة شــرعية وركوبهــا معــه يف‬\n      ‫ســيارته واختالئهــا بــه‪ ،‬لــذا كلــه مت احلكــم علــى املدعــى عليــه بحــد‬\n      ‫زنــا البكــر وذلــك بجلــده مائــة جلــدة دفعــة واحــدة علنـ ًا يف مــكان عــام‬\n      ‫وتغريبــه ســنة كاملــة مــع تــرك مــكان التغريــب جلهــات التنفيــذ وتعزيــره‬\n      ‫لقــاء مــا أســند إليــه ســوى مــا موجبــه حــد الزنــا بســجنه ملدة عشــرة أشــهر‬\n      ‫وجلــده مائتــان وخمســون جلــدة علــى خمــس دفعــات‪ ،‬كمــا ثبتــت إدانــة‬\n      ‫املدعــى عليهــا بإقامــة عالقــة محرمــة مــع رجــل ال حتــل لــه واختالئهــا‬\n\n‫‪229‬‬\n\f‫ومت احلكــم بتعزيرهــا لقــاء ذلــك بســجنها مــدة شــهرين وتســقط عقوبــة‬\n‫الســجن بحفــظ املدعــى عليهــا جزأيــن مــن القــرآن الكــرمي خــال‬\n‫ثمانيــة أشــهر وأخــذ التعهــد القــوي بعــدم العــودة إلــى مــا بــدر منهــا‪،‬‬\n‫بعــرض احلكــم علــى املدعــى عليــه قــرر اعتراضــه علــى احلكــم بالئحــة‬\n‫كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة‪ ،‬وقــررت‬\n‫املدعــى عليهــا القناعــة‪ ،‬قــدم املدعــى عليــه الئحــة اعتراضيــة تتضمــن‬\n‫رجوعــه عــن اإلقــرار بالزنــا‪ ،‬وحيــث أن رجــوع املدعــى عليــه عــن إقــراره‬\n‫بذلــك شــبهة توجــب درء حــد الزنــا عنــه إال أنــه ال يعفيــه مــن تبعتــه‬\n‫فيمــا موجبــه التعزيــر ألن التعزيــر يثبــت بالشــبهة‪ ،‬قــرر ناظــر القضيــة‬\n‫الرجــوع عمــا حكــم بــه ســابقا ومت احلكــم بــدرء حــد زنــا البكــر عنــه‬\n‫وتعزيــره لقــاء مــا أســند إليــه ســوى مــا موجبــه حــد الزنــا بالســجن ملــدة‬\n‫عشــرة أشــهر واجللــد مائتــان وخمســون جلــدة‪ .‬واحلكــم بإثبــات إدانــة‬\n‫املدعــى عليــه مبــا أســند إليــه يف دعــوى املدعــي العــام ودعــوى املدعــي‬\n‫باحلــق اخلــاص مــن التســبب يف هــروب املدعــى عليهــا وإخفاءهــا وتغييبهــا‬\n‫عــن ذويهــا لفتــرة طويلــة‪ ،‬والتغريــر بهــا وإقامــة عالقــات محرمــة معهــا‪،‬‬\n‫ومــا أســند إليــه يف دعــوى املدعــي العــام أيض ـ ًا مــن الدخــول إلــى منــزل‬\n‫أهلهــا لغــرض االعتــداء علــى العــرض‪ ،‬وتوجيــه التهمــة القويــة لــه بفعــل‬\n‫فاحشــة الزنــا باملدعــى عليهــا‪ ،‬وتعزيــره لقــاء ذلــك مبــا يلــي‪ :‬أوالً‪ :‬للحــق‬\n‫العــام بســجنه ملــدة ســنتني ونصــف وجلــده مائتــان وخمســون جلــدة علــى‬\n‫خمــس دفعــات ثاني ـاً‪ :‬للحــق اخلــاص بســجنه ملــدة ســنة ونصــف اعتبــار ًا‬\n‫مــن نهايــة محكوميتــه للحــق العــام وجلــده مائــة وثمانــون جلــدة علــى‬\n‫ثــاث دفعــات‪ ،‬بعــرض احلكــم علــى املدعــى عليــه واملدعــي باحلــق‬\n‫اخلــاص قــرر اعتراضهمــا علــى احلكــم بالئحــة اعتراضيــة كمــا قــرر‬\n\n\n                                                                                       ‫‪230‬‬\n\f      ‫املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة‪ ،‬وبعــد رفــع احلكــم‬\n                                    ‫حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم ‪ 33620566‬وتاريــخ ‪ 1433/10/23‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331879261‬وتاريــخ ‪ 1433/10/23‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1433/11/02‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 00‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪...‬مبوجــب التكليــف الصــادر مــن هيئــة‬\n      ‫التحقيــق واإلدعــاء العــام بنجــران رقــم ه ـ ن ‪ 11178/2/1‬بتاريــخ‬\n      ‫‪1430/12/29‬ه ـ وادعــى علــى الغائبــة عــن مجلــس احلكــم ‪...‬ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬واحلاضــر معــه يف مجلس احلكم‬\n      ‫‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬قائــا يف دعــواه‬\n      ‫عليهمــا فباالطــاع علــى محضــر البــاغ املقــدم مــن ‪ ... /‬هويــة وطنيــة‬\n      ‫رقــم (‪ )...‬املتضمــن تغيــب ابنتــه ‪...‬عــن املنــزل بتاريــخ ‪1433/5/27‬ه ـ‬\n      ‫وذلــك بعــد البحــث عنهــا ولكــن لــم يجدهــا وقــد خرجــت ابنتــه مــن‬\n      ‫املنــزل وهــي تلبــس ســروال وقميــص أســودين ووصــف ابنتــه بأنهــا بيضــاء‬\n      ‫البشــرة متينــة البنيــة طويلــة القامــة ذات شــعر طويــل ويرغــب يف البحــث‬\n      ‫عنهــا ‪ ،‬وقــد اتهــم يف تغييبهــا كل مــن ‪.../‬ســجل مدنــي رقــم (‪ )...‬و ‪.../‬‬\n      ‫هويــة وطنيــة رقــم (‪( )...‬حفظــة الدعــوى بحقهمــا ولــم يوجــه لهمــا أي‬\n      ‫اتهــام لعــدم كفايــة األدلــة ضدهمــا اســتنادا للمــادة (‪ )124‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة ) ‪ .‬وورد خطــاب مــن ســعادة رئيــس دائــرة التحقيــق‬\n\n‫‪231‬‬\n\f‫واالدعــاء العــام مبحافظــة اإلحســاء رقــم (ه ـ ن‪ )10727/3/2‬وتاريــخ‬\n‫‪1433/9/23‬ه ـ املتضمــن بأنــه وردهــم خطــاب مديــرة مؤسســة رعايــة‬\n‫الفتيــات رقــم (‪ )2/251‬يف ‪1433/9/20‬ه ـ بشــأن إيقــاف النزيلــة لديهــم‬\n‫‪... /‬بتاريــخ ‪1433/9/18‬ه ـ واملتهمــة يف قضيــة تغيــب عــن منــزل ذويهــا‪،‬‬\n‫وتضمــن خطــاب املؤسســة رغبــة والدهــا يف اســتالمها ومت التوجيــه‬\n‫بإطــاق ســراحها يف حــال كــون جرميتهــا غيــر موجبــة للتوقيــف وأخــذ‬\n‫التعهــد علــى والدهــا باملراجعــة بهــا جلهــة التحقيــق عنــد طلبهــا ويف حــال‬\n‫وجــود متهــم لتســبب يف تغيبهــا فيتــم بعــث األوراق للجهــة املختصــة‬\n‫للتحقيــق معــه وذلــك باخلطــاب رقــم (ه ـ ن‪)13686/2/2/1‬يف‬\n‫‪1433/9/23‬هــ‪ .‬وورد محضــر القبــض رقــم (بــدون) وتاريــخ‬\n‫‪1433/10/4‬ه ـ املعــد مــن قبــل مركــز شــرطة الفيصليــة املتضمــن أنــه‬\n‫مت إيقــاف املتهــم ‪.../‬هويــة وطنيــة رقــم (‪ )...‬مــن قبــل إدارة التحريــات‬\n‫والبحــث اجلنائــي وذلــك مســاء يــوم الثالثــاء املوافــق ‪1433/10/3‬ه ـ ثــم‬\n‫مت بعثــه ملركــز شــرطة الفيصليــة بتاريــخ ‪1433/10/4‬ه ـ ‪ .‬التصــرف‬\n‫باملتهمــن ‪ /‬مت إيقــاف املتهــم ‪...‬وإحالتــه إلى شــعبة الســجن العام اســتنادا‬\n‫للقــرار الــوزاري رقــم (‪ )1900‬يف ‪1428/7/9‬ه ـ ومت إطــاق ســراح‬\n‫املتهمــة ‪...‬بالكفالــة احلضوريــة‪ .‬وبســماع أقــوال املتهمــة ‪... /‬أقــرت‬\n‫بهروبهــا مــن منــزل والدهــا الواقــع يف حــي ‪...‬قبــل حوالــي ثالثــة أو أربعــة‬\n‫أشــهر وركبــت مــع عائلــة ال تعرفهــم يف ســيارة كبيــرة ال تعــرف نوعهــا‬\n‫بهــا أربعــة نســاء وشــخص كبيــر يف الســن إليصالهــا إلــى منطقــة جــازان‬\n‫ثــم ســألت املتهــم ‪... /‬الــذي هربــت مــن أجلــه فوصــف لهــا منــزل أهلــه‬\n‫وذهبــت إليــه وبقيــت عنــده منــذ هروبهــا حتــى بدايــة شــهر رمضــان ‪ ،‬ثــم‬\n‫قــام والــد املتهــم ‪... /‬بإرســالها عــن طريــق الطيــران إلــى املنطقــة الشــرقية‬\n\n\n                                                                                        ‫‪232‬‬\n\f      ‫لكــي تقــوم بالبــاغ عــن ابنــه يف احملكمــة أو الشــرطة وعنــد وصولهــا‬\n      ‫ملطــار املنطقــة الشــرقية ذهبــت إلــى احملكمــة اجلزئيــة وأبلغــت أحــد‬\n      ‫القضــاة هنــاك مبــا حــدث لهــا ‪ ،‬وقــام بإبــاغ الشــرطة وإحالتهــا لــدار‬\n      ‫رعايــة الفتيــات وأنهــا ال تعلــم عــن ســبب قيامهــا بهــذه التصرفــات‪ ،‬وأنهــا‬\n      ‫تســتطيع التعــرف علــى املتهــم عندمــا تشــاهده وأنهــا لــم تتعــرض إلــى أي‬\n      ‫اعتــداء مــن املتهــم ‪... /‬أو غيــره وأن املتهــم ‪... /‬يعمــل عســكري يف مدينة‬\n      ‫حفــر الباطــن وأنهــا تصــدر منهــا تصرفــات غريبــة وتقــوم باالســتفراغ‪.‬‬\n      ‫وبســماع أقــوال املتهــم‪... /‬أفــاد بأنــه قــد تعــرف علــى املتهمــة ‪...‬قبــل ســنة‬\n      ‫تقريب ـ ًا عــن طريــق االنترنــت ثــم بــدأ يكلمهــا ‪ ،‬وبعــد ذلــك قابلهــا يف‬\n      ‫منــزل أهلهــا مرتــن ومــارس معهــا فاحشــة الزنــا واتفــق معهــا علــى الزواج‬\n      ‫لكــن أهلهــا رفضــوا ذلــك ثــم طلبــت منــه أن يحضــر لهــا ويأخذهــا مــن‬\n      ‫منــزل أهلهــا وذلــك يف شــهر جمــادى األولــى مــن عــام ‪1433‬ه ـ وعنــد‬\n      ‫حضــوره إلــى املنــزل خرجــت لــه إلــى املنــزل وركبــت معــه‪ ،‬واجتهــا إلــى‬\n      ‫مدينــة حفــر الباطــن وبقيــت معــه يف شــقته ملــدة ثالثــة أشــهر ثــم اجتهــا‬\n      ‫إلــى منطقــة جيــزان وبقيــا ملــدة ثالثــة أيــام لكــي يقومــا بالذهــاب إلــى‬\n      ‫احملكمــة حتــى يتــم تزويجهمــا ولكــن لــم يتــم اســتقبالهما ثــم رجعــا‬\n      ‫إلــى مدينــة الدمــام ‪ ،‬ودخلــت املتهمــة ‪...‬إلــى قاضــي احملكمــة ثــم ذهــب‬\n      ‫هــو إلــى جهــة عملــه ‪ ،‬ثــم أبلغتــه بــأن القاضــي ســيبلغ والدهــا ويتــم حــل‬\n      ‫األمــور وأن أهلــه ليــس لديهــم أي علــم باملوضــوع وأن كل ذلــك كان‬\n      ‫برضاهــا‪ .‬وباســتجواب املتهــم ‪... /‬أقــر بأنــه تعــرف علــى الفتــاة عــن طريق‬\n      ‫األنترنــت ثــم عــن طريــق اجلــوال ثــم طلبــت منــه أن يقابلهــا يف منزلهــا‬\n      ‫مرتــن ويف املــرة الثانيــة جلــس معهــا يف املزرعــة املجــاورة ملنزلهــا داخــل‬\n      ‫البيــت وقامــا بفعــل فاحشــة الزنــا ثــم اتصلــت عليــه وطلبــت منــه أن‬\n\n\n‫‪233‬‬\n\f‫يحضــر ملدينــة جنــران لكــي يأخذهــا مــن عنــد أهلهــا ويذهبــا إلــى‬\n‫احملكمــة ليتــم تزويجهمــا‪ ،‬كــون والدهــا رفــض زواجهــا بــه لكونــه‬\n‫أســمر البشــرة ويف شــهر ربيــع الثانــي حضــر إلــى مدينــة ‪ ......‬عنــد‬\n‫احملكمــة لكــي تقابــل أحــد القضــاة هنــاك لكــي يتــم تزويجهمــا ثم مت‬\n‫اســتدعائه مــن قبــل عملــه ومت تســليمه إلــى البحــث اجلنائــي مبنطقــة‬\n‫جنــران‪ ،‬وأنــه فعــل بهــا فاحشــة الزنــا وذلــك بإيــاج ذكــره يف فرجهــا‬\n‫كمــا يفعــل الــزوج بزوجتــه وذلــك بعــد أن طلبــت منــه ذلــك وطلبــت منــه‬\n‫أن ينــزل املنــي يف فرجهــا حتــى حتمــل منــه ويرضــى والدهــا باألمــر‬\n‫الواقــع فيزوجهمــا وأنــه يرغــب بالــزواج منهــا وأنــه أعطاهــا جهــاز جــوال‬\n‫وشــريحة جديــدة‪ .‬وباســتجواب املتهمــة ‪ / ...‬أقــرت بأنهــا تعرفــت علــى‬\n‫املتهــم ‪...‬عــن طريــق االنترنــت ثــم عــن طريــق اجلــوال ‪ ،‬ثــم أخذهــا مــن‬\n‫منزلهــا مبدينــة جنــران ‪ ،‬حيــث كانــت يف غيــر وعيهــا وكانــت حتــس‬\n‫بــأن امــرأة أخــذت بيدهــا حتــى ركبــت مــع املتهــم ‪...‬يف ســيارته ‪ ،‬وذهبــا‬\n‫إلــى شــقة ‪...‬بحفــر الباطــن وبقيــت معــه مــدة طويلــة ال حتصيهــا‪ ،‬وال‬\n‫تــدري هــل فعــل بهــا فاحشــة الزنــا أم ال ‪ ،‬ألنهــا ال تــدرك مــا يحصــل لهــا‬\n‫ثــم أرســلها إلــى أهلــه يف مدينــة جــازان مــن مدينــة الريــاض‪ .‬ثــم اســتقبلها‬\n‫شــاب ال تعرفــه مــن املطــار ( اتضــح أنــه أخــو املتهم ‪...‬واســمه ‪ )...‬وأوصلها‬\n‫إلــى بيــت أهــل ‪ ،...‬وأخبــرت والــد ‪...‬ووالدتــه مبــا حصــل ( فــرزت لهــم‬\n‫أوراق مســتقلة إليوائهــم للفتــاة املتغيبــة عــن ذويهــا وقيــدت بالقيــد‬\n‫رقــم‪11030‬س وتاريــخ ‪1433/10/16‬ه ـ ) وخيرهــا والــد ‪...‬بــن أن يبلــغ‬\n‫الشــرطة أو أن يبلــغ أهلهــا ‪ ،‬ورفضــت أن يبلــغ أهلهــا خلوفهــا منهم وطلبت‬\n‫منــه أن يرســلها للمحكمــة العامــة مبدينــة الدمــام ‪ ،‬وعنــد وصولهــا‬\n‫للقاضــي باحملكمــة ‪ ،‬وأخبرتــه مبــا حصل لها أبلغ الشــرطة ‪ .‬ومبواجهة‬\n\n\n                                                                                       ‫‪234‬‬\n\f      ‫املتهــم ‪...‬باملتهمــة ‪...‬أقــر بأنــه أرســل الفتــاة مــن الريــاض إلــى جــازان عــن‬\n      ‫طريــق الطيــران‪ ،‬وأن الــذي اســتقبلها يف املطــار هــو أخــوه ‪...‬وطلــب منــه‬\n      ‫أن يوصلهــا إلــى بيــت أهلــه بجــازان وعندمــا أخبرتهــم املتهمــة ‪...‬مبــا‬\n      ‫حصــل طلــب والــده منــه أن يأتــي ويأخذهــا لعــدم عالقتــه مبــا حصــل‬\n      ‫لهمــا ‪ ،‬وبقيــت عنــد أهلــه ملــدة أربعــة أيــام ثــم جــاء وأخذهــا مــن بيــت‬\n      ‫أهلــه واســتأجر شــقة ملــدة ثالثــة أيــام ‪ ،‬ثــم ذهــب بهــا إلــى احملكمــة‬\n      ‫مبدينــة الدمــام وقــد انتهــى التحقيــق إلــى توجيــه االتهــام إلــى ‪.../‬‬\n      ‫بالتســبب يف هــروب وإخفــاء فتــاة وتغييبهــا عــن ذويهــا لفتــرة طويلــة‬\n      ‫والدخــول إلــى منزلهــا لغــرض االعتــداء علــى العــرض وفعــل فاحشــة‬\n      ‫الزنــا بالفتــاة وإقامــة عالقــات محرمــة معهــا والتغريــر بهــا ‪ ،‬وإلــى ‪...‬‬\n      ‫بالهــروب والتغيــب عــن منــزل ذويهــا وإقامــة عالقــات محرمــة مع شــخص‬\n      ‫أجنبــي عنهــا وممارســة فاحشــة الزنــا معــه‪ .‬وذلــك لألدلــة والقرائــن‬\n      ‫التاليــة ‪ -1 :‬إقرارهمــا حتقيقــا املنــوه عنهــا واملدونــان علــى ص (‪)8-1‬‬\n      ‫مــن دفتــر التحقيــق رقــم ( ‪ )2‬ومــا ورد بأقوالهمــا األوليــة لــدى جهــة‬\n      ‫االســتدالل املنــوه عنهــا واملــدون علــى ص (‪ )8-3‬مــن دفتــر االســتدالل‬\n      ‫لفــة (‪ -2 . )204‬محضــر املواجهــة املنــوه عنــه واملــدون علــى ص (‪)9‬مــن‬\n      ‫دفتــر التحقيــق رقــم ( ‪ -3 . ) 2‬تطابــق بعــض مــا ورد بأقــوال املتهمــة ‪...‬مــع‬\n      ‫مــا ورد بأقــوال املتهــم ‪ .... /‬وحيــث إن مــا أقــدم عليه املتهمان املذكوران‬\n      ‫فعــل محــرم شــرع ًِا ومعاقــب عليــه شــرعا لــذا أطلــب إثبــات إدانتهمــا مبــا‬\n      ‫أســند إليهمــا واحلكــم عليهمــا مبــا يلــي‪ -1 :‬حــد الزانــي غيــر احملصــن‬\n      ‫بحــق املتهــم ‪... /‬واملتهمــة‪ -2 .... /‬عقوبــة تعزيريــة زاجــرة لهمــا ورادعــة‬\n      ‫لغيرهمــا لقــاء بقيــة مــا أســند إليهمــا ( علمــا أن احلــق اخلــاص الزال قائمــا‬\n      ‫)هــذه دعــواي وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n\n\n‫‪235‬‬\n\f‫ا فقــد تعرفــت علــى املدعى‬   ‫العــام يف دعــواه صحيــح كلــه جملــة وتفصيـ ً‬\n‫عليهــا ‪...‬قبــل ســنة تقريبـ ًا عــن طريــق االنترنــت‪ ،‬ثــم طلبــت منــي مقابلتهــا‬\n‫يف منــزل والدهــا مرتــن ويف املــرة الثانيــة جلســت معهــا يف املزرعــة‬\n‫املجــاورة للمنــزل وقمنــا بفعــل فاحشــة الزنــا‪ ،‬وبعــد فتــرة مــن الزمــن‬\n‫اتصلــت بــي وطلبــت منــي أن أحضــر ملدينــة جنــران لكــي آخذهــا مــن‬\n‫عنــد أهلهــا ونذهــب إلــى احملكمــة ليتــم تزويجنــا ببعضنــا‪ ،‬ألن والدهــا‬\n‫رفــض زواجــي بهــا لكونــي أســمر البشــرة‪ ،‬فحضــرت إلــى مدينــة‬\n‫جنــران واصطحبــت املدعــى عليهــا يف ســيارتي إلــى مقــر عملــي مبدينــة‬\n‫حفــر الباطــن واســتأجرت شــقة هنــاك ملــدة ثالثــة أشــهر تقريب ـاً‪ ،‬وقــد‬\n‫فعلــت باملدعــى عليهــا فاحشــة الزنــا وذلــك بإيــاج ذكــري يف فرجهــا‬\n‫كمــا يفعــل الــزوج بزوجتــه وذلــك بعــد أن طلبــت منــي ذلــك وأن أنــزل‬\n‫املنــي يف فرجهــا حتــى حتمــل منــي ويرضــى والدهــا باألمــر الواقــع‬\n‫فيزوجنــا ببعضنــا‪ ،‬ثــم قمــت بإرســال املدعــى عليهــا إلــى جــازان عــن‬\n‫طريــق الطيــران واســتقبلها أخــي هنــاك وطلبــت منهــا أن تذهــب إلــى‬\n‫احملكمــة لتطلــب مــن القاضــي أن يزوجهــا منــي‪ ،‬وقــد ندمــت علــى مــا‬\n‫فعلــت إال أننــي أحــب املدعــى عليهــا ومتعلــق بهــا وأرغــب بالــزواج منهــا و‬\n‫والدهــا يرفــض ذلــك‪ ،‬وأنــا غيــر محصــن ولــم يســبق لــي الــزواج أبــداً‪،‬‬\n‫وليــس علــي ســوابق هــذه إجابتي‪.‬أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وبعــد دراســة القضيــة واالطــاع علــى أوراق املعاملــة ومبــا أن‬\n‫ا‬\n‫املدعــى عليــه أقــر مبــا جــاء يف دعــوى املدعــي العــام جملــة وتفصي ـ ً‬\n‫فأقــر بتســببه يف هــروب املدعــى عليهــا وإخفاءهــا وتغييبهــا عــن ذويهــا‬\n‫لفتــرة طويلــة‪ ،‬والتغريــر بهــا وإقامــة عالقــات محرمــة معهــا‪ ،‬والدخــول‬\n‫إلــى منــزل أهلهــا لغــرض االعتــداء علــى العــرض‪ ،‬وألن املدعــى عليــه أقــر‬\n\n\n                                                                                        ‫‪236‬‬\n\f      ‫بفعــل فاحشــة الزنــا باملدعــى عليهــا وذلــك بإيــاج ذكــره يف فرجهــا‬\n      ‫كمــا يفعــل الــزوج بزوجتــه وإنزالــه املنــي فيــه‪ ،‬ولقــول اهلل تعالــى‪ (:‬وال‬\n      ‫تقربــوا الزنــا انــه كان فاحشــة وســاء ســبيال ) وقولــه عــز وجــل (الزانيــة‬\n      ‫والزانــي فاجلــدوا كل واحــد منهمــا مائــة جلــدة وال تأخذكــم بهمــا‬\n      ‫رأفــة يف ديــن اهلل إن كنتــم تؤمنــون بــاهلل واليــوم اآلخــر وليشــهد‬\n      ‫عذابهمــا طائفــة مــن املؤمنــن) وقــول النبــي صلــى اهلل عليــه وســلم‪(:‬‬\n      ‫البكــر بالبكــر جلــد مائــة ونفــي ســنة) رواه مســلم‪ ،‬وألنــه قــد توافــرت‬\n      ‫يف املدعــى عليــه شــروط حــد الزنــا وانتفــت عنــه موانعــه‪ ،‬وألنــه غيــر‬\n      ‫محصــن‪ ،‬وألن املدعــى عليــه جمــع إلــى فعــل فاحشــة الزنــا التغريــر‬\n      ‫باملدعــى عليهــا والتســبب يف هروبهــا وإخفاءهــا وتغييبهــا عــن ذويهــا‬\n      ‫لفتــرة طويلــة‪ ،‬والدخــول إلــى منــزل أهلهــا لغــرض االعتــداء علــى‬\n      ‫العــرض‪ ،‬وألن مــا أقــدم عليــه املدعــى عليــه منكــر عظيــم وانتهــاك‬\n      ‫لألعــراض احملرمــة واســتحالل لهــا بغيــر حــق‪ ،‬وألن املدعــى عليــه أظهــر‬\n      ‫التوبــة والنــدم والرجــوع عــن اخلطــأ والعــزم علــى عــدم العــود‪ ،‬وألنــه ليــس‬\n      ‫عليــه ســوابق‪ ،‬واســتناد ًا إلــى قــرار املجلــس القضــاء األعلــى رقــم‬\n      ‫‪ 311/45‬وتاريخ‪1418/6/18‬ه ـ والقاضــي بــأن علــى القضــاة إذا نظــروا‬\n      ‫يف قضيــة زنــا البكــر وثبــت موجــب احلــد أن يحكمــوا بحــد زنــا البكــر‬\n      ‫وهــو اجللــد والتغريــب ويتــرك مــكان التغريــب وكيفيتــه للجهــات املعنية‬\n      ‫بذلك‪.‬أ‪.‬ه ـ ولــكل مــا تقــدم مــن أســباب فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه مبــا أســند إليــه وقــررت تعزيــره لقــاء ذلــك مبــا يلــي‪ :‬أوالً‪ :‬إقامــة حــد‬\n      ‫زنــا البكــر عليــه وذلــك بجلــد مائــة جلــدة دفعــة واحــدة علنـ ًا يف مــكان‬\n      ‫عــام وتغريبــه ســنة كاملــة وال حتســب منهــا املــدة التــي أمضاهــا موقوفـ ًا‬\n      ‫قبــل احلكــم‪ ،‬مــع تــرك مــكان التغريــب وكيفيتــه جلهــات التنفيــذ‪.‬‬\n\n\n‫‪237‬‬\n\f‫ثاني ـاُ‪ :‬تعزيــره لقــاء مــا أســند إليــه ســوى مــا موجبــه حــد الزنــا بســجنه‬\n‫ملــدة عشــرة أشــهر يحتســب منهــا املــدة التــي أمضاهــا موقوف ـ ًا وجلــده‬\n‫مائتــان وخمســون جلــدة علــى خمــس دفعــات بــن كل دفعــة واألخــرى ما‬\n‫ال يقــل عــن أســبوع يحتســب منهــا املــدة التــي أمضاهــا موقوفـ ًا قبــل تاريــخ‬\n‫النطــق بهــذا احلكــم‪ .‬وبذلــك حكمــت كمــا قــررت إرجــاء محاكمــة‬\n‫املدعــى عليهــا إلــى حــن إحضارهــا اســتناد ًا إلــى املــادة (‪ )141‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة وبعــرض احلكــم علــى املدعــى عليــه قــرر اعتراضــه‬\n‫علــى احلكــم بالئحــة اعتراضيــة لــذا واســتناد ًا إلــى املــواد (‪)195-194‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة فســيتم تســليمه صــورة مــن احلكــم هــذا‬\n‫اليــوم وأفهــم أن مــدة االعتــراض ثالثــون يوم ـ ًا تبــدأ مــن يــوم غــد فــإذا‬\n‫مضــت املــدة ولــم يقــدم الالئحــة االعتراضيــة فــإن حقــه يف طلــب‬\n‫االســتئناف يســقط وترفــع املعاملــة حملكمــة االســتئناف دون الئحــة‬\n‫اعتراضيــة خــال خمســة وأربعــن يومـ ًا مــن تاريــخ النطــق باحلكــم ففهــم‬\n‫ذلــك كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة‬\n‫فألجــل ذلــك قــررت رفــع كامــل أوراق املعاملــة ملقــام محكمــة‬\n‫االســتئناف لتدقيــق احلكــم حســب املتبــع كمــا قــرر املدعــي العــام‬\n‫اعتراضــه علــى احلكــم بــدون الئحــة وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينا محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪ 1433/11/02‬هـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران ويف يــوم الثالثــاء املوافــق‪ 1433/11/23‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 30:1‬للنظــر يف الالئحــة االعتراضيــة املقدمــة مــن املدعــى‬\n‫عليــه وقــد حضــر يف هــذه اجللســة املدعــي العــام واملدعــى عليــه وجــرى‬\n‫منــي االطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه‬\n\n\n                                                                                       ‫‪238‬‬\n\f      ‫واملكونــة مــن صفحتــن والتــي تتضمــن رجــوع املدعــى عليــه عــن إقــراره‬\n      ‫بالزنــا‪ ،‬ثــم جــرى منــي عــرض ذلــك علــى املدعــى عليــه وســؤاله عــن ذلــك‬\n      ‫فقــال إننــي أقــرر رجوعــي عــن إقــراري بالزنــا فالصحيــح أننــي طيلــة‬\n      ‫فتــرة بقــاء املدعــى عليهــا معــي لــم أمســها أبــد ًا ولــم أقــم بفعــل فاحشــة‬\n      ‫الزنــا بهــا وأطلــب درء حــد الزنــا عنــي وأمــا مــا ســوى ذلــك ممــا جــاء‬\n      ‫يف جوابــي فالزلــت مقــر ًا به‪.‬أ‪.‬ه ـ وبســؤال املدعــي العــام هــل لديــه بينــة‬\n      ‫تثبــت ارتــكاب املدعــى عليــه لفاحشــة الزنــا ســوى إقــراره بذلــك الــذي‬\n      ‫رجــع عنــه‪ ،‬قــال ليــس لــدي ســوى مــا جــاء يف الئحــة الدعــوى وأوراق‬\n      ‫املعاملة‪.‬أ‪.‬ه ـ وقــد حضــر يف هــذه اجللســة املدعــي باحلــق اخلــاص ‪...‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وادعــى علــى احلاضــر معــه يف‬\n      ‫ا يف دعــواه عليــه إننــي والــد املدعــى‬\n                                               ‫مجلــس احلكــم املدعــى عليــه ‪...‬قائـ ً‬\n      ‫عليهــا ‪...‬وقــد فجعــت صبيحــة يــوم اخلميــس املوافــق ‪1433/5/27‬ه ـ‬\n      ‫أنــا وأســرتي باختفــاء ابنتــي ‪...‬فجــأة وبــدون مقدمــات عــن البيــت ونــزل‬\n      ‫علينــا هــذا اخلبــر املؤلــم كالصاعقــة‪ ،‬كيــف ال وهــو خبــر ميــس العــرض‬\n      ‫والشــرف الــذي أغلــى مــا ميلكــه اإلنســان وقــد قمنــا بإخبــار اجلهــات‬\n      ‫الرســمية املختصــة ذات العالقــة مبــا حصــل ويف الوقــت ذاتــه لــم نتوقــف‬\n      ‫نحــن عــن البحــث عنهــا يف كل مــكان يف األوديــة ويف اجلبــال ويف‬\n      ‫اآلبــار واألماكــن املهجــورة وقطعنــا املســافات الطويلــة‪ ،‬فــواهلل إننــا‬\n      ‫نبحــث والظــروف النفســية والبدنيــة واملعنويــة يف أســوأ مــا ميكــن وال‬\n      ‫يعلــم بحالنــا إال اهلل ســبحانه وتعالــى ولــم نكــن نعــرف للراحــة وال للنــوم‬\n      ‫وال للمــأكل وال للمشــرب طعــم بــل أنــه بعــد مضــي مــا يقــارب شــهر مــن‬\n      ‫البحــث واجلهــد لــم نعــد نحــس بالتفكيــر أو بالتركيــز مــن وقــع هــذا‬\n      ‫االبتــاء مــن املجهــود املبــذول ليــا ونهــارا ومــع ذلــك لــم نقــف مكتــويف‬\n\n\n‫‪239‬‬\n\f‫األيــدي وكنــت أنــا والــد الفتــاة بشــكل يومــي أتابــع أدق التفاصيــل مــن‬\n‫اجلهــات الرســمية لعــل وعســى ولكــن دون جــدوى وكانــت كل ســاعة‬\n‫متــر كأنهــا يــوم وكل يــوم كأنــه شــهر وكل شــهر كأنــه ســنة‪ ،‬ومــا‬\n‫أن أتانــي اتصــال مــن اجلهــات الرســمية مــن املنطقــة الشــرقية يخبروننــي‬\n‫بالعثــور عــن ابنتــي بعــد مضــي قرابــة أربعــة أشــهر إال هرعــت مســرعا‬\n‫متجهــا إلــى املنطقــة الشــرقية وقــد وجــدت ابنتــي يف حالــة ال يعلمهــا إال‬\n‫اهلل فقــد كانــت متعبــة ومنهــارة وتائهــة وتبــن لنــا بعــد متابعــة حالتهــا‬\n‫الصحية وجود أعراض (ســحر) ونحن اآلن يف مراحل العالج مع متابعة‬\n‫دائمــة مــع املشــايخ والقــراء وال حــول وال قــوة إال بــاهلل العلــي العظيــم‪،‬‬\n‫وأننــي أســكن مــع والــدي رحمــه اهلل وأقاربــي منــذ مــا يقــارب خمســن‬\n‫عامــا يف جنــران‪ ،‬ونتمتــع وهلل احلمــد بســيرة عطــرة ومباركــة بشــهادة‬\n‫مــن عاشــوا معنــا وعرفونــا ولكــن وبعــد مــا حصــل لنــا مــن جــراء هــذه‬\n‫املصيبــة لــم يعــد لنــا طيبــة للعيــش يف هــذا املــكان الــذي ولــد بعضنــا‬\n‫فيــه وترعــرع وأصبــح كل واحــد منــا يبحــث عــن مــكان آمــن يعيــش‬\n‫فيــه خــارج جنــران وقــد تشــتت اجلميــع وتفرقنــا وقمنــا بعــرض كل مــا‬\n‫منلــك مــن عقــار للبيــع بأقــل مــن ســعرها املســتحق وذلــك لرغبــة اجلميــع‬\n‫باخلــروج مــن املنطقــة فحســبنا اهلل ونعــم الوكيــل‪ ،‬فضيلــة الشــيخ كل‬\n‫هــذه األضــرار واملآســي التــي حلقــت بــي وبأســرتي تســبب بهــا املدعــى‬\n‫عليــه ألنــه هــو مــن أخــذ ابنتــي مــن منزلــي بغيــر رضــى منهــا وال شــعور‬\n‫أو إدراك وقــام بتغييبهــا عنــا قرابــة أربعــة أشــهر دون أن نعلــم عنهــا أي‬\n‫أثــر واهلل العالــم مــا الــذي فعلــه بهــا لذلــك أطلــب مــن فضيلتكــم تعزيــر‬\n‫املدعــى عليــه لقــاء ذلــك وتطبيــق أشــد العقوبــة املنصــوص عليهــا شــرعا‬\n‫فيمــا أقــدم عليــه اجلانــي مــن جــرم ومــن آثــار ســيئة نفســية وصحيــة‬\n\n\n                                                                                     ‫‪240‬‬\n\f      ‫وماليــة وبدنيــة وخالفــات وشــتات هــذه دعــواي وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه وســؤاله اجلــواب أجــاب بقولــه مــا ذكــره املدعــي باحلــق‬\n      ‫اخلــاص يف دعــواه مــن أننــي أخــذت ابنتــه املدعــى عليهــا مــن منزلــه وأنهــا‬\n      ‫بقيــت معــي قرابــة أربعــة أشــهر فهــذا صحيــح وأمــا مــا ذكــره مــن أننــي‬\n      ‫أخذتهــا مــن منزلــه بغيــر رضــى منهــا وال شــعور أو إدراك فهــذا غيــر‬\n      ‫صحيــح والصحيــح أنهــا خرجــت معــي بطواعيــة وطلــب منهــا‪ ،‬وأمــا‬\n      ‫مــا ذكــره مــن أن ذلــك تســبب لــه وألســرته باألضــرار املذكــورة فــا‬\n      ‫علــم لــي بذلــك وال أوافــق علــى طلبــه إيقــاع عقوبــة تعزيريــة علــي لقــاء‬\n      ‫ذلــك هــذه إجابتي‪.‬أ‪.‬ه ـ وبطلــب البينــة مــن املدعــى عليــه علــى مــا دفــع‬\n      ‫بــه مــن أن املدعــى عليهــا قــد خرجــت برضاهــا واختيارهــا قــال ال بينــة‬\n      ‫لــدي علــى ذلك‪.‬أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد‬\n      ‫دراســة القضيــة واالطــاع علــى وقائــع الدعــوى وأوراق املعاملــة‪ ،‬ومبــا‬\n      ‫أن املدعــى عليــه أنكــر أخيــر ًا فعلــه لفاحشــة الزنــا باملدعــى عليهــا وقــرر‬\n      ‫رجوعــه عــن إقــراره بذلــك وطلــب درء احلــد عنــه‪ ،‬وألن املدعــي العــام‬\n      ‫لــم يقــم بينــة موصلــة تثبــت إدانــة املدعــى عليــه مبــا أســند إليــه مــن فعــل‬\n      ‫فاحشــة الزنــا باملدعــى عليهــا ســوى إقــراره الــذي رجــع عنــه‪ ،‬وألن رجــوع‬\n      ‫املدعــى عليــه عــن إقــراره بذلــك شــبهة توجــب درء حــد الزنــا عنــه إال أنــه‬\n      ‫اليعفيــه مــن تبعتــه فيمــا موجبــه التعزيــر ألن التعزيــر يثبــت بالشــبهة‪،‬‬\n      ‫وألن هــذا اإلقــرار وإن رجــع عنــه أخيــر ًا أمــام احملكمــة إال أنــه قرينــة‬\n      ‫قويــة توجــه لــه التهمــة بصحــة نســبة ذلــك إليــه ال ســيما وأنــه أقــر بذلــك‬\n      ‫ا أمــام جهــة التحقيــق وأمــام احملكمــة‪ ،‬ومبــا أن املدعــى‬     ‫إقــرار ًا مفصـ ً‬\n      ‫عليــه أقــر مبــا جــاء يف دعــوى املدعــي العــام ومــا جــاء يف دعــوى املدعــي‬\n      ‫باحلــق اخلــاص مــن تســببه يف هــروب املدعــى عليهــا وإخفاءهــا وتغييبهــا‬\n\n\n‫‪241‬‬\n\f‫عــن ذويهــا لفتــرة طويلــة‪ ،‬والتغريــر بهــا وإقامــة عالقــات محرمــة معهــا‪،‬‬\n‫ومــا جــاء يف دعــوى املدعــي العــام مــن دخولــه إلــى منــزل أهلهــا لغــرض‬\n‫االعتــداء علــى العــرض‪ ،‬وألن املدعــى عليــه دفــع بــأن ذلــك برضــى منهــا‬\n‫واختيــار وطواعيــة وألن هــذا الدفــع غيــر مقبــول إذ أن رضــى املدعــى‬\n‫عليهــا علــى فــرض ثبوتــه ال يحــل لــه ذلــك وال يجيــزه لــه‪ ،‬وألن مــا‬\n‫أقــدم عليــه املدعــى عليــه منكــر عظيــم وانتهــاك لألعــراض احملرمــة‬\n‫واســتحالل لهــا بغيــر حــق‪ ،‬ومبــا أن مــا ذكــره املدعــي باحلــق اخلــاص يف‬\n                    ‫دعــواه مــن األضــرار املترتبــة عليــه جــراء مــا أقــدم عليــه‬\n‫املدعــى عليــه هــي أضــرار ظاهــرة متحققــة ال تفتقــر إلــى إثبــات وال‬\n‫تعوزهــا البينــة‪ ،‬ال ســيما مــع إقــرار املدعــى عليــه مبــا أســند إليــه يف‬\n‫ذلــك‪ ،‬وألن املدعــى عليــه أظهــر التوبــة والنــدم والرجــوع عــن اخلطــأ‬\n‫والعــزم علــى عــدم العــود‪ ،‬وألنــه ليــس عليــه ســوابق‪ ،‬ولــكل مــا تقــدم‬\n‫مــن أســباب وتأسيس ـ ًا عليــه فقــد قــررت الرجــوع عمــا حكمــت بــه‬\n‫ســابق ًا علــى املدعــى عليــه مــن إقامــة حــد زنــا البكــر عليــه وتعزيــره‬\n‫لقــاء مــا أســند إليــه ســوى مــا موجبــه حــد الزنــا بالســجن ملــدة عشــرة‬\n‫أشــهر واجللــد مائتــان وخمســون جلــدة‪ .‬وحكمــت أخيــر ًا بإثبــات إدانــة‬\n‫املدعــى عليــه مبــا أســند إليــه يف دعــوى املدعــي العــام ودعــوى املدعــي‬\n‫باحلــق اخلــاص مــن التســبب يف هــروب املدعــى عليهــا وإخفاءهــا وتغييبهــا‬\n‫عــن ذويهــا لفتــرة طويلــة‪ ،‬والتغريــر بهــا وإقامــة عالقــات محرمــة معهــا‪،‬‬\n‫ومــا أســند إليــه يف دعــوى املدعــي العــام أيض ـ ًا مــن الدخــول إلــى منــزل‬\n‫أهلهــا لغــرض االعتــداء علــى العــرض‪ ،‬ووجهــت لــه التهمــة القويــة‬\n‫بفعلــه فاحشــة الزنــا باملدعــى عليهــا‪ ،‬وقــررت تعزيــره لقــاء ذلــك مبــا‬\n‫يلــي‪ :‬أوالً‪ :‬للحــق العــام بســجنه ملــدة ســنة ونصــف اعتبــار ًا مــن تاريــخ‬\n\n\n                                                                                         ‫‪242‬‬\n\f      ‫توقيفــه وجلــده مائتــا جلــدة علــى أربــع دفعــات بــن كل دفعــة واألخــرى‬\n      ‫مــا ال يقــل عــن أســبوع‪ .‬ثاني ـاً‪ :‬للحــق اخلــاص بســجنه ملــدة ســنة اعتبــار ًا‬\n      ‫مــن تاريــخ توقيفــه وجلــده مائــة وخمســون جلــدة علــى ثــاث دفعــات بــن‬\n      ‫كل دفعــة واألخــرى مــا ال يقــل عــن أســبوع‪ .‬وبذلــك حكمــت كمــا‬\n      ‫قــررت إرجــاء محاكمــة املدعــى عليهــا إلــى حــن إحضارهــا اســتناد ًا‬\n      ‫إلــى املــادة (‪ )141‬مــن نظــام اإلجــراءات اجلزائيــة وبعــرض احلكــم علــى‬\n      ‫املدعــى عليــه واملدعــي باحلــق اخلــاص قــررا اعتراضهمــا علــى احلكــم‬\n      ‫بالئحــة اعتراضيــة لــذا واســتناد ًا إلــى املــواد (‪ )195-194‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة فقــد جــرى إفهامهمــا مبراجعــة احملكمــة يــوم غــد‬\n      ‫األربعــاء املوافــق ‪1433/11/24‬ه ـ لتســليمهما نســخة مــن إعــام احلكم‬\n      ‫وأن مــدة االعتــراض ثالثــون يومـ ًا فــإذا مضــت املــدة ولــم يقــدم الالئحــة‬\n      ‫االعتراضيــة فــإن حقــه يف طلــب االســتئناف يســقط وترفــع املعاملــة‬\n      ‫حملكمــة االســتئناف دون الئحــة اعتراضيــة خــال خمســة وأربعــن‬\n      ‫يوم ـ ًا مــن تاريــخ النطــق باحلكــم ففهــم ذلــك كمــا قــرر املدعــي العــام‬\n      ‫اعتراضــه علــى احلكــم بــدون الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n             ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‪1433/11/23‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران واملنــدوب حــا ًال باحملكمــة العامــة باخلبــر مبوجــب قــرار معالــي‬\n      ‫رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 23336‬وتاريــخ ‪1433/12/26‬ه ـ‬\n      ‫ويف هــذا اليــوم الســبت املوافــق ‪1434/3/28‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 9 : 41‬بنــاء علــى ورود املعاملــة مــن احملكمــة اجلزائيــة بنجــران‬\n      ‫لهــذه احملكمــة برقــم ‪ 34564505‬يف ‪1434/3/24‬ه ـ وبرفقهــا قــرار‬\n      ‫املالحظــة الصــادر مــن الدائــرة اجلزائيــة الثالثــة برقــم ‪ 3442226‬يف‬\n\n\n‫‪243‬‬\n\f‫‪1434/2/19‬ه ـ واملتضمــن مــا نصــه بعــد املقدمــة‪ (:‬بعــد االطــاع علــى‬\n‫قرارنــا املرفــق باملعاملــة رقــم (‪ )348349‬وتاريــخ ‪1434/1/11‬ه ـ وحيــث‬\n‫أن املالحظــة يف صلــب احلكــم تقــرر إعــادة املعاملــة لبعثهــا لفضيلــة‬\n‫حاكمهــا يف مقــر عملــه حاليــا باحملكمــة العامــة باخلبــر الســتكمال‬\n‫اإلجابــة علــى املالحظــة بقرارنــا املشــار إليــه وإحلــاق مــا يجريــه يف القــرار‬\n‫ثــم بعــث املعاملــة للمحكمــة الصــادر منهــا القــرار إلحلــاق مــا أجــراه‬\n‫فضيلتــه بالضبــط وصورتــه وإعــادة املعاملــة إلينــا إلكمــال الزمها)‪.‬أ‪.‬ه ـ‬\n‫وقــد جــرى منــي االطــاع علــى قــرار املالحظــة الصــادر مــن الدائــرة‬\n‫اجلزائيــة الثالثــة برقــم ‪ 348349‬يف ‪1434/1/11‬ه ـ واملتضمــن املالحظــة‬\n‫علــى احلكــم مبــا نصــه بعــد املقدمــة‪( :‬وبدراســة القــرار وصــورة ضبطــه‬\n‫والئحتــي االعتــراض وأوراق املعاملــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n‫ملالحظــة مــا يلــي‪ :‬أوالً‪ :‬قــرر فضيلتــه رجوعــه عــن احلكــم علــى املدعــى‬\n‫عليــه بحــد الزانــي البكــر وقــرر تعزيــره ولــم جنــد فضيلتــه درأ احلــد‬\n‫عنــه‪ ،‬ثاني ـاً‪ :‬اجلــزاء احملكــوم بــه علــى املدعــى عليــه يف احلــق اخلــاص‬\n‫والعــام قليــل جــدا والبــد مــن جــزاء رادع وزاجــر يتناســب مــع مــا أقــدم‬\n‫عليــه‪ .‬فعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم واهلل املوفــق‪.‬‬\n‫قاضــي اســتئناف …… ختــم وتوقيــع قاضــي اســتئناف ‪ ...‬ختــم وتوقيــع‬\n‫رئيــس الدائــرة ‪...‬ختــم وتوقيــع) ‪.‬أ‪.‬ه ـ وأجيــب أصحــاب الفضيلــة رئيــس‬\n‫وقضــاة االســتئناف بالدائــرة الثالثــة لتدقيق القضايــا اجلزائية مبحكمة‬\n‫االســتئناف مبنطقــة عســير علــى مــا تفضلــوا بــه مــن املالحظــة علــى‬\n‫احلكــم محــل التدقيــق مبــا يلــي‪ :‬أوالً‪ :‬لوجاهــة مــا ذكــره أصحــاب‬\n‫الفضيلــة يف املالحظــة األولــى وملــا مت تفصيلــه يف أســباب احلكــم مــن‬\n‫موجبــات درأ احلــد فقــد قــررت درأ حــد زنــا البكــر عــن املدعــى عليــه‬\n\n\n                                                                                         ‫‪244‬‬\n\f      ‫ثاني ـاً‪ :‬لوجاهــة مــا ذكــره أصحــاب الفضيلــة يف املالحظــة الثانيــة وملــا‬\n      ‫مت تفصيلــه يف أســباب احلكــم مــن ظــروف محيطــة باجلرميــة مــع مراعــاة‬\n      ‫كــون املدعــى عليــه أظهــر التوبــة والنــدم والعــزم علــى عــدم العــود وأنــه‬\n      ‫ليــس عليــه ســوابق فقــد قــررت الرجــوع عمــا حكمــت بــه يف مقــدار‬\n      ‫العقوبــة التعزيريــة يف احلــق العــام واخلــاص فقــط يف الفقــرة أو ًال وثاني ـ ًا‬\n      ‫ليكــون نصهــا بعــد التعديــل‪« :‬أوالً‪ :‬للحــق العــام بســجنه ملــدة ســنتني‬\n      ‫ونصــف اعتبــار ًا مــن تاريــخ توقيفــه وجلــده مائتــان وخمســون جلــدة علــى‬\n      ‫خمــس دفعــات بــن كل دفعــة واألخــرى مــا ال يقــل عــن أســبوع‪ .‬ثاني ـاً‪:‬‬\n      ‫للحــق اخلــاص بســجنه ملــدة ســنة ونصــف اعتبــار ًا مــن نهايــة محكوميتــه‬\n      ‫للحــق العــام وجلــده مائــة وثمانــون جلــدة علــى ثــاث دفعــات بــن كل‬\n      ‫دفعــة واألخــرى مــا ال يقــل عــن أســبوع‪ .‬وبذلــك حكمــت»‪ .‬هــذا مــا لــزم‬\n      ‫بيانــه واجلــواب عليــه وقــررت بعــث املعاملــة إلــى احملكمــة اجلزائيــة‬\n      ‫بنجــران لرصــد مــا أحلــق بالقــرار يف ضبــط القضيــة وعــرض ما حكمت‬\n      ‫بــه أخيــر ًا علــى املدعــي العــام واملدعــى عليــه ومــن ثــم إعــادة رفــع كامــل‬\n      ‫أوراق املعاملــة ملقــام محكمــة االســتئناف حســب املتبــع وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                       ‫‪1434/3/28‬ه ـ ‪.‬‬\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪...‬القاضي املنتدب يف احملكمة اجلزائية‬\n      ‫بنجــران بنــاء علــى قــرار رئيــس املجلــس األعلــى للقضــاء رقــم (‪)709‬‬\n      ‫وتاريــخ ‪1434/02/30‬ه ـ وبنــاء علــى توجيــه فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة للعمــل باملكتــب القضائــي اخلامــس رقــم ‪ 34753980‬بتاريــخ‬\n      ‫‪1434/03/25‬ه ـ ويف هــذ اليــوم األربعــاء املوافــق ‪1434/09/16‬ه ـ‬\n      ‫أفتتحــت اجللســة الســاعة ‪ 01:30‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n\n\n‫‪245‬‬\n\f‫عليهــا األولــى ‪...‬واملعرفــة مــن قبــل والدهــا ‪...‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهــا‬\n‫األولــى أجابــت قائلــة مــا ذكــره املدعــي العــام يف دعــواه مــن الهــروب‬\n‫عــن منــزل أهلــي فغيــر صحيــح والصحيــح أنــه أتانــي شــخص ال أعرفــه‬\n‫أخذنــي مــن منــزل أهلــي وأنــا يف غيــر وعيــي وكنــت أحــس بــأن امــرأة‬\n‫تأخــذ بيــدي حتــى ركبــت مــع الشــخص الــذي ال أعرفــه وقــد يكــون‬\n‫املتهــم ‪...‬يف ســيارته وذهــب بــي إلــى شــقته التي ال أعــرف مكانها وبقيت‬\n‫عنــده مــدة طويلــة ال أحصيهــا وال أدري هــل فعــل بــي فاحشــة الزنــا أم‬\n‫ال ‪ ،‬ألنــي ال أدرك مــا يحصــل ثــم ذهبــت للمحكمــة العامــة مبدينــة‬\n‫الدمــام ‪ ،‬وعنــد وصولــي للقاضــي باحملكمــة وأخبرتــه مبــا حصــل لــي‬\n‫وحضــر والــدي واســتلمني منهــم وقــد تبــت إلــى اهلل وندمــت علــى مــا‬\n‫فعلــت وليــس علــي ســوابق هــذه إجابتي‪.‬أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وبعــد دراســة القضيــة واالطــاع علــى أوراق املعاملــة‬\n‫ومبــا أن املدعــى عليهــا أقــرت بخروجهــا مــع رجــل ال متت له بصلة شــرعية‬\n‫وركوبهــا معــه يف ســيارته واختالئهــا بــه ألن إقامــة عالقــة غيــر شــرعية‬\n‫مــع األجنبــي واالختــاء احملــرم بــه أمــر محــرم شــرعا لقــول النبــي صلــى‬\n‫اهلل عليــه وســلم‪(:‬ما خلــى رجــل بامــرأة إال كان الشــيطان ثالثهمــا)‪،‬‬\n‫كمــا أنــه طريــق مــن طــرق الوقــوع يف الفاحشــة وقــد قــال تعالى‪{:‬يــا أيهــا‬\n‫الذيــن آمنــوا ال تتبعــوا خطــوات الشــيطان}‪ ،‬ونظــرا ألن املدعــى عليهــا‬\n‫أظهــرت التوبــة والنــدم والرجــوع عــن اخلطــأ والعــزم علــى عــدم العــود‪،‬‬\n‫ولعــدم وجــود ســوابق علــى املدعــى عليهــا‪ ،‬ولــكل مــا تقــدم وتأسيس ـ ًا‬\n‫عليــه فقــد ثبــت لــدي إدانــة املدعــى عليهــا مبــا أســند إليهــا مــن إقامــة‬\n‫عالقــة محرمــة مــع رجــل ال حتــل لــه واختالئهــا وقــررت تعزيرهــا لقــاء‬\n\n\n                                                                                      ‫‪246‬‬\n\f      ‫ذلــك كلــه بســجنها ملــدة شــهرين يحتســب منهــا املــدة التــي أمضتهــا‬\n      ‫موقوفــة وتســقط عقوبــة الســجن بحفــظ املدعــى عليهــا جزئــن مــن‬\n      ‫القــرآن الكــرمي خــال ثمانيــة أشــهر مــن تاريــخ ‪1434/9/17‬ه ـ وأخــذ‬\n      ‫التعهــد القــوي بعــدم العــودة إلــى مــا بــدر منهــا وبعــرض احلكــم علــى‬\n      ‫املدعــي عليهــا قــررت قناعتهــا بــه وقــرر املدعــي العــام عــدم اعتراضــه‬\n      ‫علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                          ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/16‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم ‪......‬‬\n      ‫وتاريــخ ‪1434/5/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضي‬\n      ‫باحملكمــة الشــيخ‪ ..... /‬برقــم ‪ .....‬وتاريــخ ‪1433/11/3‬ه ـ اخلــاص‬\n      ‫بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪ ...... /‬و‪ .....‬يف قضيــة (عالقــة محرمــة)‬\n      ‫علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل فيــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة‬\n      ‫ـاء علــى قرارنــا رقــم (‪ )3442226‬وتاريــخ ‪1434/2/19‬ه ـ ‪.‬‬            ‫ضبطــه بنـ ً‬\n      ‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى‬\n                                      ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪247‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":228,"source_page_end":247,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fd2135ccc008368dbfb2cc24f41a870d9088c76a35408aab11947bf53f49b57e","normalized_text_hash":"399dfdaf3dd4eb5d9674eefa06ac6768edae8e432a26c0ed8037cee23e31ba37","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p228-33446401"},{"id":"7e4cf1f9-2916-5dd5-a5f9-0ac8386f6be3","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -زنا احملصنة -رجوع عن اإلقرار بالزنا-ادعاء اإلكراه على الزنا -احلدود تدرأ بالشبهات -تعزير بالسجن واجللد مع التوصية","document_number":"33466642","case_number":"33652352","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر باالشتراك مع فضيلة القاضي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/27","year":"1434","subject":"زنا -زنا احملصنة -رجوع عن اإلقرار بالزنا-ادعاء اإلكراه على الزنا -احلدود تدرأ بالشبهات -تعزير بالسجن واجللد مع التوصية","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33466642 :‬تاريخه ‪1434/11/27 :‬هـ‬\n                     ‫رقم الدعوى‪33652352 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 3439714‬تاريخه‪1434/2/17 :‬هـ‬\n\n\n  ‫زنــا‪ -‬زنــا احملصنــة ‪ -‬رجــوع عــن اإلقــرار بالزنا‪-‬ادعــاء اإلكــراه على الزنا‬\n  ‫‪ -‬احلــدود تــدرأ بالشــبهات ‪ -‬تعزيــر بالســجن واجللــد مــع التوصيــة‬\n                                                                     ‫باإلبعــاد‪.‬‬\n\n\n\n\n  ‫‪ .1‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬هــا تركتمــوه يتــوب فيتــوب‬\n                                                                         ‫اهلل عليــه )‬\n  ‫‪ .2‬مــا روي عــن عمــر ‪-‬رضــي اهلل عنــه‪ -‬أنــه ُأتــي بامــرأة قــد زنــت فقالــت‪:‬‬\n  ‫( إنــي كنــت نائمــة فلــم أســتيقظ إال برجــل قــد جثــم علـ َّـي‪ ،‬فخلــى‬\n                                                                          ‫ســبيلها )‪.‬‬\n  ‫‪ .3‬قــال صاحــب الشــرح الكبيــر‪ ( :‬ومتــى رجــع املقــر باحلــد عــن إقــراره‬\n  ‫قبــل منــه وإن رجــع يف أثنــاء احلــد لــم يتمــم وجملــة ذلــك أن شــرط‬\n  ‫إقامــة احلــد باإلقــرار بالبقــاء عليــه إلــى متــام احلــد فــإن رجــع عــن‬\n  ‫إقــراره كــف عنــه )‪ ،‬قــال صاحــب اإلنصــاف ( هــذا املذهــب يف جميــع‬\n                                                         ‫احلــدود ) (‪207/26‬ـ ‪)208‬‬\n\n\n\n\n  ‫دعــوى املدعــي العــام ضــد املدعــى عليهــا (محصنــة) باتهامهــا بفعــل‬\n  ‫فاحشــة الزنــا وذلــك بعدمــا مت القبــض عليهــا بعــد وضعهــا مولــود ًا نتــج‬\n\n                                                                                         ‫‪248‬‬\n\f      ‫عــن حملهــا ســفاح ًا وطلــب املدعــي العــام احلكــم عليهــا بحــد الزانيــة‬\n      ‫احملصنــة‪ ،‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليهــا أنكرتهــا‪،‬‬\n      ‫ودفعــت بــأن فعــل الفاحشــة كان باإلكــراه‪ ،‬بعــرض إقرارهــا حتقيقــا‬\n      ‫عليهــا دفعــت باإلكــراه عليــه‪ ،‬جــرى االطــاع علــى التقريــر الطبــي‬\n      ‫املتضمــن أن املدعــى عليهــا أدخلــت املستشــفى إثــر والدة طبيعيــة‪،‬‬\n      ‫نظــر ًا لدفــع املدعــى عليهــا باإلكــراه علــى فعــل الفاحشــة‪ ،‬وألن إدعــاء‬\n      ‫اإلكــراه شــبهة يــدرأ بهــا احلــد واحلــدود تــدرأ بالشــبهات ‪ -‬لــذا كلــه‬\n      ‫حكمــت احملكمــة بصــرف النظــر عــن إقامــة حــد الزانــي احملصــن‬\n      ‫عليهــا وتعزيرهــا للتهمــة القويــة بســجنها ملــدة ســنة ونصــف وبجلدهــا‬\n      ‫مائــة وخمســن جلــدة مفرقــة علــى ثــاث دفعــات مــع التوصيــة بإبعادهــا‬\n      ‫عــن البــاد بعــد انتهــاء فتــرة محكوميتهــا ‪ -‬بعــرض احلكــم عليهمــا‬\n      ‫قــرر املدعــي العــام املعارضــة علــى احلكــم واالكتفــاء بالئحــة الدعــوى‬\n      ‫كالئحــة اعتراضيــة وقــررت املدعــى عليهــا القناعــة باحلكــم‪ ،‬وبعــد‬\n                      ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بعرعــر باالشــتراك مــع فضيلــة القاضــي‪ .../‬وفضيلــة القاضــي‪.../‬‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعرعــر برقــم ‪ 33652352‬وتاريــخ ‪1433/11/14‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 332011530‬وتاريــخ ‪1433/11/14‬ه ـ ففــي هــذا اليــوم االثنــن‬\n      ‫املوافق‪1433/11/22‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا قــدم‬\n      ‫املدعــي العــام ‪...‬الئحــة دعــواه ضــد ‪...‬حاملــة رخصــة إقامــة ‪...‬قائــا إنــه‬\n\n‫‪249‬‬\n\f‫يف يــوم الثالثــاء املوافــق ‪1433/10/17‬ه ـ مت القبــض علــى املدعــى عليها‬\n‫مــن قبــل مركــز شــرطة الفيصليــة وذلــك بعــد وضعهــا مولــود ًا نتــج عــن‬\n‫حملهــا ســفاح ًا وباســتجوابها أقــرت بحملهــا ســفاح ًا وممارســتها فعــل‬\n‫فاحشــة الزنــا برضاهــا مرتــن قبــل عــدة أشــهر مــع وافــد مــن اجلنســية‬\n‫الهنديــة يدعــى‪( ... /‬مت فــرز أوراق خاصــة جلهــة اإلختصــاص للقبــض‬\n‫عليــه) وذلــك بإيــاج ذكــره يف فرجهــا وإنــزال مــاءه بداخلهــا وقــد حصــل‬\n‫ذلــك داخــل عمــارة أمــام منــزل كفيلهــا وأنــه ســافر خــارج البــاد وال‬\n‫تعرف أي معلومات عنه وقد صدر بحقها التقرير الطبي من مستشــفى‬\n‫عرعــر املركــزي رقــم (‪ )10137‬وتاريــخ ‪1433/10/16‬ه ـ والــذي‬\n‫تضمــن ( أن املدعــى عليهــا أدخلــت املستشــفى بتاريــخ ‪1433/10/11‬ه ـ‬\n‫إثــر والدة طبيعيــة بحمــل مكتمــل واملولــود ذكــر يــزن ‪ 2‬كيلــو) وقــد‬\n‫انتهــى التحقيــق مــع املدعــى عليهــا ‪ ...‬إلــى اتهامهــا بفعــل فاحشــة الزنــا‬\n‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬ماجــاء بأقوالهــا املدونــة مبحضــر‬\n‫االســتجواب لفــة (‪ )15‬صفحــة ‪ -2 3-2-1‬مــا جــاء بإقرارهــا املــدون‬\n‫مبحضــر االســتجواب لفــة (‪ )15‬صفحــة ‪ -3 4‬ماجــاء يف التقريــر الطبــي‬\n‫املرفــق لفــة (‪ )11‬وحيــث إن مــا أقدمــت عليــه املدعى عليها وهي بكامل‬\n‫أهليتهــا املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات‬\n‫إدانتهــا مبــا أســند إليهــا واحلكــم عليهــا بحــد الزانيــة احملصنــة ويف نفس‬\n‫اجللســة حضــرت املدعــى عليهــا ‪...‬حتمــل رخصــة إقامــة رقــم ‪...‬واملعــرف‬\n‫عليهــا مــن قبــل الســجانة ‪ ...‬فجــرى ســؤالها عمــا جــاء يف دعــوى املدعــي‬\n‫العــام فأجابــت قائلــة وهــي حتســن العربيــة مــا جــاء يف دعــوى املدعــي‬\n‫العــام غيــر صحيــح والصحيــح أنــي كنــت أعمــل لــدى كفيلــي يف حــي‬\n‫الناصريــة وخرجــت أثنــاء ذلــك ألرمــي املهمــات فوجدنــي عامــل هنــدي‬\n\n\n                                                                                     ‫‪250‬‬\n\f      ‫فمســكني بالقــوة وأدخلنــي إلــى داخــل عمــارة حديثــة البنــاء أمــام منــزل‬\n      ‫كفيلــي وقــام باغتصابــي وأدخــل ذكــره يف فرجــي ممــا نتــج عــن ذلــك‬\n      ‫حملــي منــه هكــذا أجابــت ثــم ســألنا املدعيــة عــن ديانتهــا فأجابــت‬\n      ‫أنهــا علــى ديــن اإلســام ثــم جــرى ســؤالها هــل هــي محصنــة فأجابــت‬\n      ‫قائلــة نعــم أنــا متزوجــة وعنــدي ولديــن ولكــن طلقنــي زوجــي ثــم جــرى‬\n      ‫مجابهتهــا بإقرارهــا املــدون علــى لفــة (‪ )15‬صفحــة (‪ )4‬واملتضمــن ( أقــر‬\n      ‫أنــا الوافــدة ‪ ... /‬ـ أندونيســية اجلنســية ـ ـ حاملــة لرخصــة إقامــة رقــم (‪)...‬‬\n      ‫ـ ـ أقــر وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا ودون إكــراه مــن أحــد‬\n      ‫أننــي قــد حملــت ســفاح ًا مــن أحــد العمالــة الوافــدة ويدعــى ‪... /‬وهــو‬\n      ‫هنــدي اجلنســية وهــو مســافر اآلن إلــى الهنــد وال أعــرف عنوانــه وال عملــه‬\n      ‫وقــد مارســت فاحشــة الزنــا معــه مرتــن وذلــك بإدخــال ذكــره يف فرجــي‬\n      ‫وإنــزال مــاءه وقــد حصــل ذلــك يف شــهر واحــد أثنــاء خروجــي مــن منــزل‬\n      ‫كفيلــي برمــي القمامــة وقمــت بإعطائــه رقــم هاتفــي واتفقــت معــه علــى‬\n      ‫اخلــروج للعمــارة املقابلــة ملنــزل كفيلــي وقــام بفعــل الفاحشــة معــي مرتــن‬\n      ‫داخــل هــذه العمــارة ممــا نتــج عنــه حملــي ســفاح ًا ‪ ،‬كمــا أننــي مطلقــة‬\n      ‫ـوع منــي دون‬‫ويوجــد لــدي ابنــان يف أندونيســيا وإننــي مارســت الزنــا بطـ ٍ‬\n      ‫إكــراه ‪ ،‬وهــذا إقــرار منــي بذلــك فأجابــت قائلــة لقــد أكرهونــي علــى‬\n      ‫هــذا اإلقــرار فســألناها هــل لديهــا بينة على هذا اإلكــراه فأجابت قائلة‬\n      ‫ليــس لــدي بينــة ولكــن ال صحــة ملــا جــاء فيــه ثــم ســألنا املدعــي العــام هل‬\n      ‫ا ليــس لــدي ســوى مــايف أوراق املعاملــة‬       ‫لديــك زيــادة بينــة فأجــاب قائ ـ ً‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبالنظــر إلــى طيــات املعاملــة‬\n      ‫وإلــى محضــر اســتجواب املدعــى عليهــا لفــة (‪ )15‬صفحــة (‪ )4‬واملتضمــن‬\n      ‫إقــرار املدعــى عليهــا بفعــل فاحشــة الزنــا برضاهــا مرتــن وبالنظــر إلــى‬\n\n\n‫‪251‬‬\n\f‫التقريــر الصــادر مــن مستشــفى عرعــر املركــزي لفــة (‪ )11‬واملتضمــن (‬\n‫أن املدعــى عليهــا أدخلــت املستشــفى بتاريــخ ‪1433/10/11‬ه ـ إثــر والدة‬\n‫طبيعيــة ( حمــل مكتمــل ) واملولــود ذكــر يــزن ‪ 2,200‬كجــم وخرجــت‬\n‫مــن املستشــفى بتاريــخ ‪1433/10/15‬هــ) وإلدعائهــا أنهــا مكرهــة علــى‬\n‫هــذا الفعــل وعلــى هــذا اإلقــرار وألن ادعــاء اإلكــراه يتضمــن الرجــوع‬\n‫عــن اإلقــرار آنــف الذكــر والرجــوع عــن اإلقــرار يف الزنــا مقبــول عنــد‬\n‫عامــة الفقهــاء قــال صاحــب الشــرح (ومتــى رجــع املقــر باحلــد عــن إقــراره‬\n‫قبــل منــه وإن رجــع يف أثنــاء احلــد لــم يتمــم وجملــة ذلــك أن شــرط إقامــة‬\n‫احلــد باإلقــرار بالبقــاء عليــه إلــى متــام احلــد فــإن رجــع عــن إقــراره كــف‬\n‫عنــه) قــال صاحــب اإلنصــاف ( هــذا املذهب يف جميع احلــدود) ‪207/26‬ـ‬\n‫‪ 208‬وقــد رجعــت املدعــى عليهــا عــن إقرارهــا بأنهــا فعلــت هــذه الفعلــة‬\n‫مطاوعــة مختــار ًة ولذلــك ملــا هــرب ماعــز رضــي اهلل عنــه قــال النبــي‬\n‫صلــى اهلل عليــه وســلم (هــا تركتمــوه يتــوب فيتــوب اهلل عليــه ) وألن‬\n‫ادعــاء اإلكــراه شــبهة يــدرأ بهــا احلــد واحلــدود تــدرأ بالشــبهات وملــا روي‬\n‫عــن عمــر رضــي اهلل عنــه أنــه أتــي بإمــرأة قــد زنــت فقالــت ( إنــي كنــت‬\n‫نائمــة فلــم أســتيقظ إال برجــل قــد جثــم علــي فخلــى ســبيلها ) وجلميــع‬\n‫مــا تقــدم فلــم يثبــت لدينــا باإلجمــاع إدانــة املرأة‪.../‬بتمكــن الوافــد‪/‬‬\n‫‪ ...‬بــأن يفعــل فاحشــة الزنــا بهــا ممــا أدى إلــى حملهــا ســفاح ًا وقررنــا‬\n‫صــرف النظــر عــن دعــوى املدعــي العــام بإقامــة حــد الزانــي احملصــن‬\n‫عليهــا ولكــن لوجــود التهمــة القويــة فقــد قررنــا باإلجمــاع تعزيرهــا‬\n‫بســجنها ملــدة ســنة ونصــف حتســب مــن تاريــخ إيقافهــا وبجلدهــا مائــة‬\n‫وخمســن جلــدة مفرقــة علــى ثــاث دفعــات بــن كل دفعــة والتــي تليهــا‬\n‫مــاال يقــل عــن عشــرة أيــام وبذلــك حكمنــا كمــا نوصــي بإبعادهــا عــن‬\n\n\n                                                                                        ‫‪252‬‬\n\f      ‫البــاد بعــد انتهــاء فتــرة محكوميتهــا وبعــرض احلكــم عليهمــا قــرر‬\n      ‫املدعــي العــام املعارضــة علــى احلكــم واالكتفــاء بالئحــة الدعــوى‬\n      ‫كالئحــة اعتراضيــة وقــررت املدعــى عليهــا القناعــة باحلكــم وعليــه‬\n      ‫فقــد قررنــا رفــع املعاملــة إلــى محكمــة االســتئناف كاملتبــع وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪1433/11/22‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫اخلماســية األولــى يف محكمــة االســتئناف باجلــوف علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر برقــم ‪ 332011530‬وتاريــخ‬\n      ‫‪1433/11/ 30‬ه ـ املرفــق بهــا القــرار الصــادر مــن أصحــاب الفضيلــة‬\n      ‫الشــيخ ‪ ...‬والشــيخ ‪...‬والشــيخ ‪......‬برقــم ‪ .......‬وتاريــخ ‪1433/11/27‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد ‪...‬أندونيســية اجلنســية يف قضيــة‬\n      ‫فاحشــة وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة ‪ ،‬تقــرر‬\n      ‫املصادقــة علــى احلكــم مــع تنبيــه أصحــاب الفضيلــة لتعديــل احلكــم مــن‬\n      ‫صــرف النظــر عــن الدعــوى الــى درء حــد الزانــي احملصــن عــن املدعــى‬\n      ‫ـداء‬\n       ‫عليهــا لتوجــه الدعــوى بحــد الزانــي احملصــن علــى املدعــى عليهــا ابتـ ً‬\n      ‫وإلدعائهــا اإلكــراه يــدرأ احلــد وأمــا صــرف النظــر فيكــون عنــد عــدم‬\n      ‫ـداء وذلــك قبــل بعــث املعاملــة جلهــة التنفيــذ‪ .‬واهلل‬\n                                                             ‫توجيــه الدعــوى ابتـ ً‬\n               ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪253‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":248,"source_page_end":253,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4ad160205a8bc17618fce8d9555b9ce80b6d5022e6c4865345dd9fd20191bbd0","normalized_text_hash":"cdcef0d37b99cc2fce3b94e2428cac6be47938a299706eb103a2489573078330","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p248-33466642"},{"id":"683ac0d5-27a3-5550-b131-63553e8b4ff0","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -زنا غير احملصن -شبهة فعل فاحشة الزنا -التسبب يف تغييب فتاة -اخللوة بأجنبية -الرجوع عن اإلقرار بالزنا -تعزير بالسجن واجللد ومصادرة اجلواالت -احلدود تدرأ بالشبهات.","document_number":"34288327","case_number":"34197867","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة مرفق ا بها القرار","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/8","year":"1434","subject":"زنا -زنا غير احملصن -شبهة فعل فاحشة الزنا -التسبب يف تغييب فتاة -اخللوة بأجنبية -الرجوع عن اإلقرار بالزنا -تعزير بالسجن واجللد ومصادرة اجلواالت -احلدود تدرأ بالشبهات.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34288327 :‬تاريخه‪1434/5/8 :‬هـ‬\n                  ‫رقم الدعوى‪34197867 :‬‬\n  ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34209648‬تاريخه‪1434/5/8 :‬هـ‬\n\n\n‫زنــا ‪ -‬زنــا غيــر احملصــن ‪ -‬شــبهة فعــل فاحشــة الزنــا ‪ -‬التســبب يف تغييب‬\n‫فتــاة ‪ -‬اخللــوة بأجنبيــة ‪ -‬الرجــوع عــن اإلقــرار بالزنــا ‪ -‬تعزيــر بالســجن‬\n                 ‫واجللــد ومصــادرة اجلــواالت ‪ -‬احلدود تدرأ بالشــبهات‪.‬‬\n\n\n\n\n‫‪ .1‬قولــه صلــى اهلل عليــه وســلم ‪( :‬ادرؤوا احلــدود بالشــبهات) رواه‬\n                                                                     ‫التر مــذي‬\n‫‪ .2‬مذهــب احلنفيــة والشــافعية واحلنابلــة قبــول الرجــوع عــن اإلقــرار‬\n                                                                   ‫يف احلــدود‪.‬‬\n‫‪ .3‬مشــروعية التعزيــر باملــال وهــو مذهــب املالكيــة واحلنابلــة واختيــار‬\n                                                                  ‫ابــن تيميــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه األول بفعــل فاحشــة الزنــا‬\n‫والتســبب يف تغيــب فتــاة‪ ،‬وتوجيــه االتهــام للمدعــى عليــه الثانــي بإيــواء‬\n‫محــدث وفتــاة واخللــوة بهــا‪ -‬طلــب املدعــي العــام احلكــم علــى املدعــى‬\n‫عليــه األول بحــد الزانــي واحلكــم علــى املدعــى عليهمــا بعقوبــة تعزيريــة‬\n‫لقــاء مــا أســند إليهمــا مــن جرائــم تعزيريــة ومصــادرة الهاتفــن النقالــن‬\n‫املســتخدمني يف اجلرميــة وبعــرض دعــوى املدعــي العــام علــى املدعــى‬\n\n                                                                                    ‫‪260‬‬\n\f      ‫عليهمــا أنكراهــا ودفــع املدعــى عليــه الثانــي بــأن املدعــى عليــه األول‬\n      ‫قــام بتغريــره حيــث أخبــره أن املجنــي عليهــا خطيبتــه وأنــه يريــد أن يأخــذ‬\n      ‫جــزءا مــن البيــت الــذي يســكنه هــو وإياهــا فتــرة مؤقتــة وأنــه وافــق علــى‬\n      ‫ذلــك وأن اجلــزء الــذي كانــت فيــه الفتــاة مســتقل متامــا ولــم يقابــل املــرأة‬\n      ‫ولــم يدخــل عليهــا وبعــرض إقــرار املدعــى عليــه األول حتقيق ـ ًا أنكــره‬\n      ‫ودفــع أنــه لــم يقــرأه‪ ،‬وإلقــرار املدعــى عليــه بإيــواء الفتــاة وإلنــكاره‬\n      ‫ا‬\n      ‫اخللــوة وللبينــة املعدلــة شــرع ًا وألن مــا دفــع بــه غيــر مقبــول شــرع ًا وعقـ ً‬\n      ‫وحلرمــة مــا أقدمــوا عليــه وحلرمــة البلــد احلــرام لذلــك كلــه توجهــت‬\n      ‫الشــبهة للمدعــى عليــه األول بفعــل فاحشــة الزنــا وتغييــب الفتــاة وثبتــت‬\n      ‫إدانــة املدعــى عليــه الثانــي بإيــواء محــدث وفتــاة واخللــوة بهــا ومت احلكــم‬\n      ‫بصــرف النظــر عــن إقامــة حــد زنــا البكــر علــى املدعــى عليــه األول‬\n      ‫واحلكــم عليــه بتعزيــره بســجنه ســتة أشــهر وجلــده ســتني جلــدة دفعــة‬\n      ‫واحــدة‪ ،‬وتعزيــره لقــاء تغييــب الفتــاة بســجنه ســتة أشــهر تبــدأ بعــد انتهاء‬\n      ‫احملكوميــة الســابقة وجلــده ثالثمائــة جلــدة موزعــة علــى ســت دفعــات‬\n      ‫ومصــادرة الهاتــف اجلــوال وإدخــال قيمتــه يف حســاب مؤسســة النقــد‪.‬‬\n      ‫واحلكــم علــى املدعــى عليــه الثاني بتعزيره بســجنه ســنة وجلــده ثالثمائة‬\n      ‫جلــدة موزعــة علــى ســت دفعــات ومصــادرة الهاتــف اجلــوال وإدخــال قيمته‬\n      ‫يف حســاب مؤسســة النقــد‪ ،‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه الثانــي واملدعــي العــام قــرر االعتــراض بالئحــة وقــرر املدعــى عليــه‬\n      ‫األول القناعــة‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة‬\n                                                                                      ‫عليــه‪.‬‬\n\n\n\n\n‫‪261‬‬\n\f‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة اجلزائية مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املـكـرم ــة بـرق ــم ‪ 34197867‬وتاريــخ ‪1434/04/29‬هـ‬\n‫املقيــدة بالـمـحـك ــمة برقــم ‪ 341054477‬وتاريــخ ‪1434/4/29‬ه ـ فـف ــي‬\n‫ي ـ ــوم الثـالث ــاء الـمـواف ــق‪1434/04/30‬هـ افـتـتـح ــت اجلـلـس ــة الـسـاعـ ـ ــة‬\n‫‪ 01 : 45‬وفيهــا حضــر املدعــي العــام ‪ .....‬ســعودي اجلنســية املكلــف‬\n‫ا أدعــي علــى‬    ‫برقــم ه ـ م ‪ 6057 /1 /2 /‬يف ‪1433 / 1/1‬ه ـ وادعــى قائـ ً‬\n‫‪ ...... -1 :‬ســعودي اجلنســية مبوجــب الســجل رقــم ‪ .....‬و‪ ...... -2‬اجلنســية‬\n‫مبوجــب البطاقــة البديلــة رقــم ‪...‬بتاريــخ ‪1434/3/8‬ه ـ ‪ ،‬تقــدم والــد‬\n‫ـاغ عــن تغيبهــا حيــث خرجــت بتاريــخ ‪1434/3/7‬ه ـ‬         ‫الفتــاة ‪ ، ... /‬ببـ ٍ‬\n‫‪ ،‬برفقــة والدتهــا مــن الفنــدق الــذي يقيمــون فيــه وعــادت والدتهــا ولــم‬\n‫تعــد هــي وال يتهــم أحــد ًا يف ذلــك ورقــم جوالهــا (‪ )...‬وبســماع أقــوال‬\n‫والدتهــا أفــادت بأنــه عنــد وصولهــا إلــى بــاب الفنــدق توجهــت ابنتهــا‬\n‫إلــى الشــارع فنادتهــا فلــم جتبهــا وواصلــت طريقهــا ولــم تلحــق بهــا كــون‬\n‫ابنائهــا برفقتهــا وأنــه ســبق أن تغيبــت عنهــم يف الريــاض ملــدة ثالثــة أيــام‬\n‫ـراض نفســية وأنهــا أخبرتهــا بأنــه ســتعود إلــى‬‫وأنهــا ال تعانــي مــن أمـ ٍ‬\n‫احلــرم للجلــوس فيــه وبتاريــخ ‪1434/3/15‬ه ـ ‪ ،‬جــرى رصــد اتصــاالت‬\n‫متبادلــة مــن قبــل البحــث اجلنائــي بــن الرقمــن (‪ )......‬حيــث اتضــح بــأن‬\n‫الرقــم األول باســتخدام املدعــى عليــه الثانــي ‪ ،‬والــذي يســكن يف حــي‬\n‫(اجلميــزة) ثــم حضــر املدعــى عليــه األول ‪ ،‬إلــى جهــة البحــث وأرشــدهم‬\n‫إلــى مــكان وجــود الفتــاة حيــث جــرى االنتقــال والقبــض علــى املدعــى‬\n\n                                                                                         ‫‪262‬‬\n\f      ‫عليــه الثانــي ‪ ،‬ومعــه الفتــاة بداخــل شــقته وضبــط بحوزتــه ثالثــة هواتف‬\n      ‫نقالــة وأفادتهــم الفتــاة بــأن املتســبب يف تغيبهــا هــو املدعــى عليــه األول‪،‬‬\n      ‫فقبــض عليــه وضبــط بحوزتــه هاتــف نقــال وبســماع أقــوال املدعــى عليــه‬\n      ‫الثانــي ‪ ،‬أقــر بــأن املدعــى عليــه األول ‪ ،‬أحضــر لــه الفتــاة وذكــر لــه‬\n      ‫بأنهــا خطيبتــه وطلــب منــه إبقاءهــا عنــده ليذهــب إلــى أهلهــا ثــم حضــر‬\n      ‫البحــث وقبــض عليــه وأنــه لــم يجامعهــا وأن املدعــى عليــه األول ‪،‬‬\n      ‫كان مــع الفتــاة يف غرفــة مســتقلة وهــو بغرفــة أخــرى مبفــرده وبســماع‬\n      ‫املدعــى عليــه األول ‪ ،‬أقــر بأنــه جامــع الفتــاة وأنــه لــم يفــض بكارتهــا‬\n      ‫كونهــا مســتخدمة مــن قبــل وأنــه قابلهــا بالصدفــة عنــد احلــرم (وقــد‬\n      ‫جــرى فــرز أوراق مســتقلة للمتهمــة الفتــاة ‪ ، ... /‬وأحيلــت قضيتهــا إلــى‬\n      ‫دائــرة العــرض واألخــاق بالريــاض حملاكمتهــا مبقــر إقامتهــا) (كمــا‬\n      ‫جــرى فــرز أوراق للمدعــى عليــه الثانــي‪ ،‬جــراء عودتــه بعــد اإلبعــاد ‪،‬‬\n      ‫وأحيلــت إلــى جهــة االختصاص)وقــد حضــر والــد الفتــاة وقــرر تنازلــه‬\n      ‫عــن ابنتــه وعــن املتهمــن حتــى قبــض عليهــم جميعـ ًا يف الشــقة وأنــه لــم‬\n      ‫يلمــس الفتــاة ولــم يحــدث بينهمــا أي شــيء وأن رقــم جوالــه هــو (‪ )...‬وأن‬\n      ‫الرقــم اآلخــر الــوارد يف محضــر القبــض يعــود خلادمــة إندونيســية تعمــل‬\n      ‫لــدى امــرأة يف (العزيزيــة) وهــي صديقــة لوالدتــه وتدعــى الدكتــورة‬\n      ‫‪ ...‬واالتصــاالت املتبادلــة بــن الرقمــن هــي ألجــل الدكتــورة لكــي‬\n      ‫تذهــب اخلادمــة إليهــا للعمــل عندهــا وأنــه يســكن لوحــده وأنــه ســبق أن‬\n      ‫أبعــد عــن البــاد يف قضيــة جنائيــة وعــاد عــن طريــق التهريــب مــن منفــذ‬\n      ‫(الطــوال) وأنــه يحمــل اجلنســيتني ‪ :‬املصريــة واليمنيــة ‪ ،‬وأنــه اســتخدم‬\n      ‫هاتفــه األســود يف جرميتــه ‪ .‬وباســتجواب املدعــى عليــه األول ‪ ،‬أقــر بأنــه‬\n      ‫ـاج كامــل وأنهــا لــم تكــن بكــر ًا‬‫فعــل فاحشــة الزنــا بالفتــاة مرتــن بإيـ ٍ‬\n\n‫‪263‬‬\n\f‫بــل كانــت مفضوضــة وأنــه تعــرف عليهــا حــن كان عائــد ًا مــن احلــرم‬\n‫حيــث وجدهــا أمــام منزلهــم ثــم أخذهــا يف جولــة بداخــل احلــارة وأنــه‬\n‫اتصــل علــى املدعــى عليــه الثانــي ‪ ،‬الــذي طلــب منــه إحضارهــا فأخذهــا‬\n‫إليــه وركبــا معــه يف ســيارته واجتــه بهمــا إلــى بيتــه وكانــت فيــه امــرأة‬\n‫إندونيســية وأن املدعــى عليــه الثانــي ‪ ،‬حينمــا أحــس باخلطــر أراد أن‬\n‫يلبســه القضيــة وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى‬\n‫عليــه الثانــي ‪ ،‬بإيــواء محــدث وفتــاة واخللــوة بهــا ‪ ،‬واتهــام املدعــى عليــه‬\n                      ‫األول ‪ ،‬بفعــل فاحشــة الزنــا والتســبب يف تغيــب فتــاة ‪.‬‬\n‫وحيــث إن مــا قــام بــه املدعــى عليهمــا وهمــا بكامــل أهليتهمــا املعتبــرة‬\n‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ‪ ،‬لــذا أطلــب إثبــات إدانتهمــا‬\n‫مبــا أســند إليهمــا واحلكــم علــى املدعــى عليــه األول ‪ ،‬بحــد الزانــي‬\n‫البكــر ‪ ،‬واحلكــم عليهمــا بعقوبــة تعزيريــة ‪ ،‬لقــاء مــا أســند إليهمــا مــن‬\n‫جرائــم تعزيريــة ‪ ،‬واحلكــم مبصــادرة الهاتفــن النقالــن املســتخدمني‬\n‫يف اجلرميــة ‪ ،‬وهــو مــن نــوع ‪......‬الصنع‪/‬بخاصيــة شــريحتني‪ /‬رقــم‬\n‫مصنعي(‪)................‬العائــد للمدعــى عليــه الثانــي ‪ ،‬والهاتــف الثانــي مــن‬\n‫نــوع (نوكيــا ويحمــل رقــم مصنعــي (‪ ).............‬العائــد للمدعــى عليــه‬\n‫األول علم ـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل) هــذه دعــواي وبســؤال‬\n‫املدعــى عليــه أنكــر مــا جــاء يف الدعــوى هكذا أجاب وبســؤال املدعي‬\n‫العــام عــن البينــة قــال إقــراره املرفــق علــى ملف صفحــة رقم‪12‬واملتضمن‬\n‫إنــه قــام بفعــل الفاحشــة بهــا وجامعهــا وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أنكــر مــا جــاء يف إقــراره وإنــه لــم يقــرأه هكــذا أجــاب وبســؤال املدعــي‬\n‫العــام عــن البينــة عــن تغيــب املدعــى عليــه يف تغيــب الفتــاة قــال محضــر‬\n‫املواجهــة بــن املدعــى عليــه و‪...‬حيــث كان موقــف ‪ ......‬قــوي وكان‬\n\n\n                                                                                       ‫‪264‬‬\n\f      ‫موقــف املدعــى عليــه ضعيف ـ ًا ووجــود الفتــاة لــدى ‪...‬ثمانيــة أيــام ولــم‬\n      ‫يفعــل بهــا دليــل علــى أن املدعــى عليــه هــو الــذي غيــب املجنــي عليهــا لــدى‬\n      ‫‪...‬هكــذا جــاب وبعــرض ذلــك علــى املدعــى عليــه قــال ليــس بصحيــح‬\n      ‫هكــذا أجــاب ورفعــت اجللســة إلحضــار املدعــى عليــه ‪...‬ويف يــوم‬\n      ‫األحــد املوافــق‪ 1434/05/19‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر‬\n      ‫صباحــا وفيهــا حضــر املدعــي العــام واملدعــى عليــه ‪...‬وبســؤاله عمــا جــاء‬\n      ‫يف الدعــوى أجــاب قائــا بــأن املدعــى عليــه ‪...‬قــام بتغريــره حيــث إنــه‬\n      ‫أخبــره بــأن املجنــي عليهــا خطيبتــه وأنــه يريــد أن يأخــذ جــزءا مــن البيــت‬\n      ‫الــذي يســكنه هــو وإياهــا فتــرة مؤقتــة وأنــه وافــق علــى ذلــك وأن اجلــزء‬\n      ‫الــذي كانــت فيــه الفتــاة مســتقل متامــا ولــم يقابــل املــرأة ولــم يدخــل‬\n      ‫عليهــا هكــذا أجــاب وبســؤال املدعــي العــام البينــة قــال أطلــب املهلــة‬\n      ‫إلحضارهــا ويف يــوم الســبت املوافــق‪ 1434/05/25‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ )11.30‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه ‪...‬وبســؤال‬\n      ‫املدعــي العــام عمــا طلــب اإلمهــال ألجلــه قــال حضــرت البينــة وأطلــب‬\n      ‫ســماعها وعليــه حضــر ‪...‬ســعودي ســجل رقــم ‪...‬وبســؤاله عمــا لديــه مــن‬\n      ‫ا أشــهد هلل بــأن املدعــى عليــه مت التوصــل إليــه عــن‬    ‫شــهادة شــهد قائ ـ ً‬\n      ‫طريــق املكاملــة الــواردة علــى هاتفــه وجــرى االتصــال عليــه وحضــوره‬\n      ‫لدينــا بالشــرطة قســم البحــث ومت ســؤاله عــن املكاملــات الــواردة مــن‬\n      ‫جوالــه إلــى امــرأة إندونيســية وصــدر اتصــال مــن هاتــف اإلندونيســية‬\n      ‫إلــى هاتــف امــرأة بالريــاض اتضــح بعــد ذلــك أنهــا والــدة املجنــي عليهــا‬\n      ‫ثــم جاءنــا ‪...‬وأخبرنــا بوجــود فتــاة يف منــزل املدعــى عليــه ثــم متــت مداهمــة‬\n      ‫منــزل املدعــى عليــه وطرقنــا البــاب وقلنــا لــه افتــح البــاب نحــن مــن رجــال‬\n      ‫البحــث قــال ليــس عنــدي مفتــاح لبــاب الشــقة مــع أخــي وهــو يف جــدة ثــم‬\n\n\n‫‪265‬‬\n\f‫قمنــا بدفــع البــاب ووجدنــا الفتــاة معــه يف نفــس الغرفــة وكاشــفة عــن‬\n‫وجههــا هكــذا شــهد كمــا حضــر ‪...‬ســعودي ســجل رقــم ‪...‬وبســؤاله‬\n‫عمــا لديــه مــن شــهادة قــال أشــهد هلل بأننــي حضــرت وقــت املداهمــة‬\n‫ودفعنــا البــاب ووجــدت الفتــاة املجنــي عليهــا داخــل الغرفــة معــه وكانــت‬\n‫وقــت دخولــي للغرفــة مغطيــة لوجههــا وقــد دخــل الشــاهد الســابق هــو‬\n‫أو ًال للشــقة هكــذا شــهد وبســؤال املدعــى عليــه ‪...‬عمــا جــاء يف الشــهادة‬\n‫قــال كان املفتــاح مــع ‪...‬ولــم أقــل لهــم إن املفتــاح مــع أخــي ولــم تكــن‬\n‫كاشــفة وجههــا وقــت دخولهــم والــذي قــام بتغريــري ‪...‬هكــذا أجــاب‬\n‫وبســؤاله هــل كان يأتــي ‪...‬إليهــا يف الشــقة عنــدك قــال نعــم وكانــا‬\n‫يجلســان ســوي ًا يف غرفــة مســتقلة وأنــا يف غرفــة مســتقلة وبــن الغرفتــن‬\n‫فاصــل مــن البــاب الســحاب هكــذا أجــاب وبســؤال الشــاهدين هــل‬\n‫كان هنــاك بــاب بــن الغرفتــن قــاال ال نعلــم وإمنــا وجدناهــا مفتوحــة‬\n‫بعضهــا علــى بعــض ووجدنــا يف الغرفــة القريبــة مــن البــاب عــدد اثنــن‬\n‫مــن أســرة النــوم هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n‫صحيــح ويف الغرفــة الداخليــة ثــاث أســرة هكــذا أجــاب ورفعــت‬\n‫اجللســة لتعديــل الشــهود ويف يــوم الثالثــاء املوافــق‪ 1434/05/28‬ه ـ‬\n‫افتتحــت اجللســة الســاعة(‪ )10.00‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليهمــا وأحضــر املدعــي العــام للتزكيــة كال مــن ‪... -1‬ســعودي ســجل‬\n‫رقــم ‪...‬و‪... -2‬ســعودي ســجل رقــم ‪...‬وباستشــهادهما شــهدا بعدالــة وثقــة‬\n‫الشــهود فبنــاء علــى مــا تقــدم وإلنــكار املدعــى عليــه فهــد مبــا جــاء يف‬\n‫الدعــوى ولعــدم البينــة ولرجوعــه عــن إقــراره وألن ذلــك يقبــل شــرع ًا‬\n‫وهــو مذهــب احلنفيــة والشــافعية واحلنابلــة وحلديــث( ادرؤوا احلــدود‬\n‫بالشــبهات) رواه الترمــذي ولقــوة القرينــة علــى تســبب املدعــى عليــه يف‬\n\n\n                                                                                    ‫‪266‬‬\n\f      ‫تغييــب املجنــي عليهــا وألنــه مقــرر شــرع ًا التعزيــر باملــال وهــو مذهــب‬\n      ‫املالكيــة واحلنابلــة واختيــار ابــن تيميــة وحلداثــة ســن املدعــى عليــه‬\n      ‫ولعــدم ســوابق املدعــى عليــه ‪...‬وإلقــرار املدعــى عليــه ‪...‬بإيــواء ‪...‬والفتــاة‬\n      ‫وإلنــكاره اخللــوة وللبينــة املعدلــة شــرع ًا وألن مــا دفــع بــه غيــر مقبــول‬\n      ‫ا وحلرمــة مــا أقدمــوا عليــه وحلرمــة البلــد احلــرام لذلــك كلــه‬‫شــرع ًا وعقـ ً‬\n      ‫فــإن الشــبهة تتوجــه بقيــام املدعــى عليــه ‪...‬بقيامــه بفعــل فاحشــة الزنــا‬\n      ‫وتغييــب الفتــاة وثبــت لــدي إدانــة املدعــى عليــه ‪ ...‬مباجــاء يف الدعــوى‬\n      ‫وعليــه فقــد حكمــت مبايلــي أوال‪ :‬املدعــى عليــه ‪ -1 ...‬صرفــت النظــر‬\n      ‫عــن حــد زنــا البكــر‪ -2 .‬بســجنه ســتة أشــهر ابتــداء مــن تاريــخ إيقافــه‬\n      ‫وبجلــده ســتني جلــدة دفعــة واحــدة لقــاء شــبهة فعــل فاحشــة الزنــا ‪..‬‬\n      ‫‪ -3‬بســجنه ســتة أشــهر تبــدأ بعــد انتهــاء احملكوميــة الســابقة وبجلــده‬\n      ‫ثالثمائــة جلــدة موزعــة علــى ســت دفعــات متســاويات بــن كل دفعــة‬\n      ‫وأخــرى أســبوع ًا لقــاء تغييــب الفتــاة‪ -4.‬مصــادرة الهاتــف اجلــوال ذو‬\n      ‫الرقــم املصنعــي(‪ )............‬وإدخــال قيمتــه يف حســاب مؤسســة النقــد‪.‬‬\n      ‫ثانيـاً‪ :‬املدعــى عليــه الثانــي ‪ -1 ...‬بســجنه ســنة ابتــداء مــن تاريــخ إيقافــه‬\n      ‫وبجلــده ثالثمائــة جلــدة موزعــة علــى ســت دفعــات متســاويات بــن كل‬\n      ‫دفعــة وأخــرى أســبوع ًا لقــاء إيــواء محــدث وفتــاة أجنبيــة واخللــوة بهــا ‪.‬‬\n      ‫‪ -2‬مصــادرة الهاتــف اجلــوال ذو الرقــم املصنعــي (‪ )......‬وإدخــال قيمتــه‬\n      ‫يف حســاب مؤسســة النقــد‪ .‬وبعــرض احلكــم علــى املدعــي العــام قــرر‬\n      ‫اعتراضــه بالئحــة وجــرى تســليمه صــورة مــن القــرار الشــرعي وأفهــم‬\n      ‫بنظــام االســتئناف وقــررا املدعــى عليــه ‪...‬القناعــة وقــرر املدعــى عليــه ‪...‬‬\n      ‫اعتراضــه بالئحــة وجــرى تســليمه صــورة مــن القــرار الشــرعي وأفهم بإن‬\n      ‫لــه ثالثــن يومـ ًا لتقــدمي الئحتــه االعتراضيــة وإذا مضــت املــدة ولــم يقــدم‬\n\n\n‫‪267‬‬\n\f‫االعتــراض ســقط حقــه يف االعتــراض وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/28‬ه ـ ‪.‬‬\n‫احلمــدهلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكة املكرمة مرفق ًا بها القرار رقم ‪ 347209648‬يف ‪1434/5/8‬هـ‬\n‫ومضمونــه املصادقــة علــى احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                        ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                ‫‪268‬‬\n\f269\n\f270\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":260,"source_page_end":270,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e0e1906496e37426ba80ad22193efdfaeef617d7e292cd119b18cc915a111e7c","normalized_text_hash":"7d00aa93ffeb2fbc48330514401e3cb2184d6f8be5a65e34c0532cabc8f6326d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p260-34288327"},{"id":"134ae8cf-a4e1-5cb2-ac90-6416403f2116","document_type":"judgment","category":"judicial","subcategory":"general","title":"قوادة ودعارة -أدلة الشريعة على حترمي الفساد وحفظ األعراض -السوابق املوجبة لتشديد العقوبة -تعزير بالسجن والغرامة","document_number":"3411182","case_number":"3411654","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/13","year":"1434","subject":"قوادة ودعارة -أدلة الشريعة على حترمي الفساد وحفظ األعراض -السوابق املوجبة لتشديد العقوبة -تعزير بالسجن والغرامة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3411182 :‬تاريخه‪1434/1/13:‬هـ‬\n                         ‫رقم الدعوى‪3411654 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3459113‬تاريخه‪1434/3/10 :‬هـ‬\n\n\n      ‫قــوادة ودعــارة ‪ -‬أدلــة الشــريعة علــى حتــرمي الفســاد وحفــظ األعــراض‬\n      ‫‪ -‬الســوابق املوجبــة لتشــديد العقوبــة ‪ -‬تعزيــر بالســجن والغرامــة‬\n                                                                   ‫واملصــادرة ‪.‬‬\n\n\n\n      ‫‪ .1‬قولــه اهلل تعالــى (وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى‬\n                                                                 ‫اإلثــم والعــدوان)‬\n      ‫‪ .2‬وقــول النبــي صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم حــرام‬\n                                                             ‫دمــه ومالــه وعرضــه)‬\n      ‫‪ .3‬وقــد جعلــت الشــريعة الغــراء العــرض أحــد الضروريــات اخلمــس‬\n                                                             ‫والواجــب حفظهــا ‪.‬‬\n             ‫‪ .4‬املواد رقم ‪ 2‬و ‪ 3‬و ‪ 11‬من نظام مكافحة االجتار باألشخاص‪.‬‬\n\n\n\n\n      ‫أقــام املدعــي العــام دعــوى ضــد املدعــى عليــه يطلــب فيهــا إثبــات قيامــه‬\n      ‫بالقــوادة والدعــارة واحلكــم عليــه بعقوبــة تعزيريــة رادعــة وفــق املــادة ‪3‬‬\n      ‫مــن نظــام االجتــار باألشــخاص مــع تشــديد العقوبــة لســوابقه ومصــادرة‬\n      ‫جوالــه حيــث قبــض عليــه أثنــاء التنســيق بإحضــار ثــاث فتيــات لقــاء‬\n      ‫ألفــي ريــال ‪ -‬ومبواجهــة املدعــى عليــه بالدعــوى أقــر مبــا جــاء فيهــا‬\n\n‫‪271‬‬\n\f‫وعليــه قــررت احملكمــة ســجنه ثنتــي عشــرة ســنة وتغرميــه عشــرين ألــف‬\n‫ريــال ومصــادرة الهاتــف والشــريحة وقــرر املدعــى عليــه عــدم القناعــة‬\n                             ‫وجــرى التصديــق مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪3411654‬‬\n‫وتاريــخ ‪ 1434/01/07‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3443446‬وتاريــخ‬\n‫‪ 1434/01/06‬ه ـ ففــي يــوم االثنــن ‪ 1434/01/12‬ه ـ افتتحت اجللســة‬\n‫الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪ ....‬ســعودي اجلنســية حامــل‬\n‫بطاقــة أحــوال رقــم (‪ )....‬واملكلــف بالعمــل لدينــا مبوجــب خطــاب‬\n‫التكليــف ذو الرقــم (ه ـ م ‪ )368/6/2‬وتاريــخ ‪1430/12/29‬ه ـ وقــرر‬\n‫دعــواه قائــا بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعــاء العــام مبحافظــة جــدة‬\n‫ادعــي علــى ‪ )50( ....‬عامـ ًا يدعــي انــه ســعودي اجلنســية مبوجــب البطاقــة‬\n‫البديلــة رقــم (‪ )....‬غيــر متعلــم غيــر محصــن موقــوف بســجون محافظــة‬\n‫جــدة مبوجــب أمــر التوقيــف رقــم (‪ )72488‬وتاريــخ ‪1433/11/11‬ه ـ‬\n‫ومــدد توقيفــه مبوجــب أمــر متديــد التوقيــف رقــم (ه ـ م‪) 73262/3/2‬‬\n‫وتاريــخ ‪1433/11/15‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ‬\n‫‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‬\n‫ـاء علــى‬\n       ‫حيــث إنــه بتاريــخ األربعــاء ‪1433/11/10‬ه ـ مت القبــض عليــه بنـ ً‬\n‫مــا ورد عــن طريــق أحــد املصــادر الســرية عــن قيامــه بالقــوادة ويتــم‬\n‫التنســيق معــه علــى جوالــه رقــم (‪ )....‬فجــرى االتصــال عليــه والتنســيق‬\n\n                                                                                     ‫‪272‬‬\n\f      ‫معــه علــى إحضــار ثــاث فتيــات مــن اجلنســية املغربيــة مقابــل مبلــغ مالــي‬\n      ‫وقــدره (‪ )2700‬ريــال ‪ ،‬وعنــد حضــور الفرقــة شــوهد املدعــى عليــه‬\n      ‫مترجــا علــى قدميــه ‪ ،‬وعنــد اســتيقافه اســتعد بإحضــار الفتيــات‬\n      ‫شــرط حصولــه علــى املبلــغ املالــي عندهــا مت القبــض عليــه‪ ،‬وبتفتيشــه‬\n      ‫عثــر بحوزتــه علــى جــوال ‪ ......‬يحمــل الرقــم املصنعــي (‪ )............‬بنفــس‬\n      ‫الرقــم الــذي جــرى التنســيق معــه بواســطته وبســماع أقوالــه أفــاد بأنــه‬\n      ‫اتصــل عليــه شــخص علــى جوالــه وطلــب منــه إحضــار نســاء وقــال بأنــه‬\n      ‫ســوف يدفــع لــه مبلــغ ألفــي ريــال فقــال لــه أحضــر املــال وكان قصــده‬\n      ‫مــن ذلــك أن يأخــذ منــه الفلــوس وال يحضــر لــه النســاء فتــم القبــض عليــه‬\n      ‫وباســتجوابه أفــاد بأنــه أتصــل عليــه شــخص وطلــب منــه إحضــار نســاء‬\n      ‫فــرد عليــه بطلــب مــال إلحضــار النســاء فأصــر املتصــل علــى إحضــار‬\n      ‫النســاء وغرضــه هــو أخــذ املــال والهــروب بــه وانتهــى التحقيــق إلــى‬\n      ‫توجيــه االتهــام إلــى املدعــى عليــه ‪ ....‬بالقــوادة وذلــك لألدلــة والقرائــن‬\n      ‫املذكــورة مبلــف القضيــة وبالبحــث عــن ســوابقه عثــر لــه علــى (‪)21‬‬\n      ‫إحــدى وعشــرين ســابقة يف جرائــم متنوعــة بشــرب املســكر والســرقة‬\n      ‫واالختــاء احملــرم والتزويــر والفاحشــة والقــوادة وحيــث إن مــا أقــدم‬\n      ‫عليــه املدعــى عليــه وهــو بكامــل أهليتــه فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا لــذا اطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫رادعــة وفــق املــادة (‪ )3‬مــن نظــام االجتــار باألشــخاص وتشــديد العقوبــة‬\n      ‫عليهــا لســوابقه التــي لــم تردعــه العقوبــات الســابقة عــن تكــرار‬\n      ‫ارتــكاب جرائمــه ومصــادرة جهــازه اجلــوال املضبــوط بحوزتــه اســتناد ًا‬\n      ‫للمــادة (‪ )11‬مــن نظــام مكافحــة االجتــار باألشــخاص هكــذا ادعــى‬\n      ‫‪.‬وجــرى إحضــار املدعــى عليــه وبســؤاله عــن دعــوى املدعــي العــام أجــاب‬\n\n\n‫‪273‬‬\n\f‫ا‬\n‫ا كل مــا ذكــره املدعــي العــام يف دعــواه صحيــح جملــة وتفصيـ ً‬              ‫قائـ ً‬\n‫وقــد قمــت باإلتفــاق علــى القــوادة علــى النســاء عبــر جوالــي نــوع ‪......‬‬\n‫ورقــم اإلتصــال ‪ ....‬وذلــك مقابــل مبلــغ مالــي ومــا ذكــره املدعــي العــام‬\n‫مــن وجــود ســوابق مســجلة علـ ّـي وعددهــا واحــد وعشــرون ســابقة‬\n‫فصحيــح وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى فعلــي هكــذا أجــاب‬\n‫هــذا وقــد جــرى اطالعــي علــى صــورة صحيفــة ســوابق املدعــى عليــه‬\n‫املرفقــة باملعاملــة باللفــة رقــم (‪ )19‬املتضمنــة وجــود الســوابق املذكــورة‬\n‫بدعــوى املدعــي العــام فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا‬\n‫قــرره الطرفــان وبنــاء علــى مصادقــة املدعــى عليــه علــى دعــوى املدعــي‬\n‫العــام فقــد ثبــت لــدي إدانــة املدعــى عليــه املذكــور بعاليــه مبــا نســب‬\n‫إليــه يف الدعــوى مــن اتفاقــه علــى القــوادة علــى النســاء مبقابــل مالــي‬\n‫ا قبيحـ ًا وجــرأة‬ ‫محرمــا وفعـ ً‬\n                             ‫ً‬     ‫ا‬\n                                   ‫ومبــا أن مــا قــام بــه املدعــى عليــه يعــد عمـ ً‬\n‫يف الباطــل يســتحق العقــاب عليــه وفيــه نشــر للفســاد أوســاط املجتمــع‬\n‫وهــو مــن التعــاون علــى اإلثــم والعــدوان واهلل ســبحانه وتعالــى يقــول (‬\n‫وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى اإلثــم والعــدوان ) والنبــي‬\n‫صلــى اهلل عليــه وســلم يقــول‪ ( :‬كل املســلم علــى املســلم حــرام دمــه‬\n‫ومالــه وعرضــه ) وقــد جعلــت الشــريعة الغــراء العــرض أحــد الضروريــات‬\n‫اخلمــس والواجــب حفظهــا وبعــد االطــاع علــى املــواد رقــم ‪ 2‬و ‪ 3‬و ‪ 11‬مــن‬\n‫نظــام مكافحــة االجتــار باألشــخاص ونظــر ًا لكثــرة ســوابق املدعــى‬\n‫عليــه وتنوعهــا وعــدم انزجــاره دال علــى ســوء ســلوكه الســيما وأن منهــا‬\n‫ســوابق مماثلــة وهــذا يســتوجب األخــذ علــى ذلــك بحــزم ومبــا أن املدعــى‬\n‫عليــه أظهــر التوبــة والنــدم فلمــا ســبق فقــد حكمــت علــى املدعــى عليــه‬\n‫تعزيــر ًا مبــا يلــي أوالً‪ :‬يســجن املدعــى عليــه ملــدة اثنــا عشــر ســنة يحتســب‬\n\n\n                                                                                           ‫‪274‬‬\n\f      ‫موقوفــا يف هــذه القضيــة ويدفــع غرامــة ماليــة قدرهــا‬\n                                                               ‫ً‬     ‫منهــا مــا أمضــاه‬\n      ‫عشــرون ألــف ريــال وفق ـ ًا للمــادة رقــم ‪ 3‬مــن نظــام مكافحــة االجتــار‬\n      ‫ثانيــا‪ :‬مصــادرة هاتــف املدعى عليه وشــريحته املســتخدمني‬    ‫باألشــخاص ً‬\n      ‫يف اجلرميــة وعــدم صــرف الشــريحة لــه مــرة أخــرى وفقـ ًا للمــادة رقــم ‪11‬‬\n      ‫مــن النظــام املشــار إليــه وبعــرض احلكــم علــى الطرفــن قــرر املدعــي‬\n      ‫العــام عــدم معارضتــه كمــا قــرر املدعــى عليــه عــدم قناعتــه بــه طالب ـ ًا‬\n      ‫رفعــه حملكمــة االســتئناف مــن دون الئحــة اعتراضيــة وأمــرت برفــع‬\n      ‫كامــل أوراق املعاملــة حملكمــة االســتئناف مبكــة املكرمــة وجــرى‬\n      ‫النطــق باحلكــم يف يــوم االثنــن ‪1434/1/12‬ه ـ الســاعة ‪ 10 : 00‬وعلــى‬\n      ‫ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬نحــن رئيــس‬\n      ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقــة‬\n      ‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 3411182‬وتاريــخ‬\n      ‫‪1434/1/13‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ .... /‬القاضــي باحملكمــة‬\n      ‫اجلزائيــة مبحافظــة جــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪.... /‬‬\n      ‫‪ ،‬املتهــم يف قضيــة قــوادة ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n              ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،،،‬‬\n\n\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":271,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d568ce2026c6eefcadd8ee823b9333363cdeaa1e78a56d1ac8525ea982c0f3bf","normalized_text_hash":"0085eef4fafa2ef31d95c758a6d5e2e66600b3be5ff79b57ffb938dc1b957b8d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p271-3411182"},{"id":"5774d836-5251-58eb-9079-c725eb7a9e21","document_type":"judgment","category":"judicial","subcategory":"general","title":"زنا -خلوة محرمة -إقامة عالقة مع امرأة -املدعى عليهم غير محصنن -عدم وجود سوابق -ثبوت إدانة -المحكمة هي التي تعطي الفعل الوصف الذي يستحقه -تعزير بالسجن واجللد واإلبعاد عن البالد.","document_number":"3445972","case_number":"33514322","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بامللحوظات اآلتية :أو ال /فضيلته أثبت ما طلبه املدعي العام مبا أسند إلى املدعى عليهم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/24","year":"1434","subject":"زنا -خلوة محرمة -إقامة عالقة مع امرأة -املدعى عليهم غير محصنن -عدم وجود سوابق -ثبوت إدانة -المحكمة هي التي تعطي الفعل الوصف الذي يستحقه -تعزير بالسجن واجللد واإلبعاد عن البالد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3445972 :‬تاريخه‪1434/2/24:‬هـ‬\n                  ‫رقم الدعوى‪33514322 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34377145‬تاريخه‪1434/12/3 :‬هـ‬\n\n\n‫زنــا ‪ -‬خلــوة محرمــة ‪ -‬إقامــة عالقــة مــع امــرأة ‪ -‬املدعــى عليهــم غيــر‬\n‫محصنــن ‪ -‬عــدم وجــود ســوابق ‪ -‬ثبــوت إدانــة ‪ -‬احملكمــة هــي التــي‬\n‫تعطــي الفعــل الوصــف الــذي يســتحقه ‪ -‬تعزيــر بالســجن واجللــد‬\n                                                         ‫واإلبعاد عن البالد‪.‬‬\n\n\n\n‫‪ -1‬قــول اهلل تعالــى ‪« :‬إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن‬\n‫آمنــوا لهــم عــذاب أليــم يف الدنيــا و اآلخــرة واهلل يعلم وأنتم ال تعلمون»‪.‬‬\n                     ‫‪ -2‬قوله تعالى ‪« :‬وال تعاونوا على اإلثم والعدوان»‪.‬‬\n      ‫‪ -3‬قوله تعالى ‪« :‬وال تقربوا الزنا إنه كان فاحشة وساء سبيال»‪.‬‬\n‫‪ -4‬قــول النبــي صلــى اهلل عليــه وســلم ‪« :‬مــا مــن امــرأة تنــزع ثيابهــا يف‬\n‫غيــر بيتهــا إال هتكــت مــا بينهــا وبــن اهلل مــن ســتر» أخرجــه أحمــد‬\n‫يف املســند(‪ )362/6‬والطبرانــي يف املعجــم الكبيــر(‪)652/255/24‬‬\n‫وقــال الهيثمــي ‪« :‬ورجــال أحدهــا رجــال الصحيــح» وصححــه املنــذري‬\n‫واأللبانــي‪ .‬وانظــر السلســلة (‪ ، )3442‬قــال املنــاوي ‪-‬رحمــه اهلل‪ -‬يف‬\n‫شــرحه لهــذا احلديــث ‪« :‬والظاهــر أن نــزع الثيــاب عبــارة عــن تكشــفها‬\n                                ‫لألجنبــي لينــال منهــا اجلمــاع أو متعتــه»‪.‬‬\n‫‪ -5‬مــا نــص عليــه يف الكشــاف‪« :‬القــوادة التــي تفســد النســاء والرجــال‬\n‫أقــل مــا يجــب عليهــا الضــرب البليــغ‪ ،‬وينبغــي شــهرة ذلــك بحيــث‬\n‫يســتفيض يف النســاء والرجــال لتجتنــب‪ ،‬وإذا أركبــت القــوادة دابــة‬\n                                                                                    ‫‪276‬‬\n\f      ‫وضمــت عليهــا ثيابهــا ليؤمــن كشــف عورتهــا ونــودي عليهــا هــذا جــزاء‬\n      ‫مــن يفعــل كــذا وكــذا ( أي يفســد النســاء والرجــال ) كان مــن‬\n      ‫أعظــم املصالــح قالــه الشــيخ» كشــاف القنــاع (‪ ، )3032/5‬ومطالــب‬\n                                  ‫أولــي النهــى يف شــرح غايــة املنتهــى (‪.)226/6‬‬\n      ‫‪ -6‬قــول شــيخ اإلســام ابــن تيميــة ‪-‬رحمــه اهلل‪ :-‬وقولــه تعالــى «فأســر‬\n      ‫بأهلــك بقطــع مــن الليــل واتبــع أدبارهــم وال يلتفــت منكــم أحــد إال‬\n      ‫امرأتــك إنــه مصيبهــا مــا أصابهــم» فعــذب اهلل عجــوز الســوء القــوادة‬\n      ‫مبثــل مــا عــذب قــوم الســوء الذيــن كانــوا يعملــون اخلبائــث» الفتــاوى‬\n                                                                  ‫الكبــرى ‪.534/5‬‬\n      ‫‪ -7‬قــول ابــن فرحــون ‪« :‬إن رأى القاضــي املصلحــة يف قمــع الســفلة‬\n                                         ‫بإشــهارهم بجرائمهــم فعــل» (‪.)146/2‬‬\n      ‫‪ -8‬القــوادة نــوع مــن أنــواع جرميــة غســل األمــوال كمــا نصــت عليــه‬\n                            ‫املــادة (‪/3/2‬ح) مــن نظــام مكافحــة غســل األمــوال‪.‬‬\n                                   ‫‪ -9‬املادة (‪ )159‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن قبــل االدعــاء العــام علــى املدعــى عليهــم األربعــة‬\n      ‫رجــان وامرأتــان باالجتمــاع بإحــدى الشــقق املفروشــة لغــرض فاســد‬\n      ‫ودفــع الثانــي أجــرة الشــقة ألجــل هــذا الغــرض وطلــب إثبــات مــا أســند‬\n      ‫إليهــم وإيقــاع العقوبــة التعزيريــة عليهــم‪ ،‬حيــث تلقــت هيئــة األمــر‬\n      ‫باملعــروف والنهــي عــن املنكــر بالغا بقيام املدعــى عليهما األول والثاني‬\n      ‫بإدخــال املدعــى عليهمــا الثالثــة والرابعــة لفعــل الفاحشــة بهمــا‪ ،‬فجــرى‬\n      ‫االنتقــال للموقــع فلوحــظ أحدهمــا خارجــا مــن الشــقة وباســتجوابه‬\n\n‫‪277‬‬\n\f‫واســتدعاء مــن بداخــل الشــقة خــرج الثانــي وعليــه املالبــس الداخليــة‬\n‫فأقــروا أمــام الفرقــة القابضــة مبمارســة الفاحشــة وأنهــا ليســت املــرة‬\n‫األولــى‪ ،‬أقــر املدعــى عليهمــا األول والثانــي باالجتمــاع لغــرض فاســد مــع‬\n‫املرأتــن وأنكــرا فعــل الفاحشــة بهمــا كمــا أقــر املدعــى عليــه الثانــي‬\n‫بقيامــه بدفــع أجــرة الشــقة وأمــا املدعــى عليهمــا الثالثــة والرابعــة فقــد‬\n‫أنكرتــا التهمــة وأقــرت الثالثــة بأنهــم اجتمعــوا لتنــاول طعــام العشــاء‬\n‫‪ ،‬وألن املدعــى عليهــم اجتمعــوا علــى اإلثــم والعــدوان ونشــر الرذيلــة‬\n‫والفاحشــة لــذا فقــد ثبــت لــدى احملكمــة إدانتهــم باالجتمــاع يف إحــدى‬\n‫الشــقق املفروشــة لغــرض الفســاد وامتهــان الدعــارة ودفــع الثانــي مبلغــا‬\n‫ماليــا وقــررت تعزيرهــم مبــا يلــي بســجن كل واحــد منهــم أربــع ســنوات‬\n‫ابتــداء مــن تاريــخ إيقافهــم وجلــد كل واحــد منهم خمســن جلــدة تكرر‬\n‫عليــه ســت عشــرة مــرة بــن كل دفعتــن أســبوعا مــع إبعــاد املدعــى عليــه‬\n‫األول عــن البــاد ‪ -‬بعــرض احلكــم عليهــم قــرر املدعــى عليهمــا الثالثــة‬\n‫والرابعــة القناعــة بينمــا قــرر املدعــي العــام واملدعــى عليهمــا األول‬\n‫والثانــي عــدم القناعــة فأفهمــوا بتعليمــات االســتئناف ‪ -‬عــادت القضيــة‬\n‫مــن محكمــة االســتئناف بامللحوظــات اآلتيــة‪ :‬أو ًال ‪/‬فضيلتــه أثبــت مــا‬\n‫طلبــه املدعــي العــام مبــا أســند إلــى املدعــى عليهــم ‪ ،‬وأضــاف إلــى ذلــك‬\n‫وصفــا زائــدا علــى مــا طلبــه املدعــي العــام وهــو أن اجتماعهــم مــن أجــل‬\n‫الدعــارة ‪ ،‬مــع إنكارهــم ذلــك ‪ ،‬فمــا مســتند فضيلتــه علــى ذلــك ؟‪.‬‬\n‫ثانياً‪/‬املدعــى عليهــم أنكــروا دعــوى املدعــي العــام باســتثناء االجتمــاع‬\n‫مــن أجــل الفســاد ‪ ،‬وأنكــروا فعــل الفاحشــة ‪ ،‬وشــهادة الشــاهدين التــي‬\n‫اســتند فضيلتــه عليهــا تضمنــت اعتــراف املرأتــن مبمارســة الفاحشــة‬\n‫مــع املدعــى عليهمــا ‪ ،‬وهــذا االعتــراف ال يتعــدى غيرهمــا‪ .‬ثالثــا‪ /‬مــا‬\n\n\n                                                                                     ‫‪278‬‬\n\f      ‫حكــم بــه فضيلتــه كثيــر ‪ ،‬خاصــة وأنهــم غيــر محصنــن ‪ ،‬وليــس‬\n      ‫عليهــم ســوابق ‪ ،‬وال فائــدة مــن إطالــة ســجنهما ‪ -‬أجابــت احملكمــة مبــا‬\n      ‫يلــي‪ :‬األولــى ‪ /‬احملكمــة ال تتقيــد بالوصــف الــوارد يف الئحــة االدعــاء‬\n      ‫كمــا نصــت عليــه املــادة (‪ )159‬مــن نظــام اإلجــراءات اجلزائيــة بــل‬\n      ‫احملكمــة هــي التــي تعطــي الفعــل الوصــف الــذي يســتحقه ‪ .‬وبالنســبة‬\n      ‫للمالحظــة الثانيــة ‪ /‬فــإن شــهادة عضــوي الهيئــة تضمنــت اعتــراف جميع‬\n      ‫املدعــى عليهــم أمامهمــا بفعــل الفاحشــة واالجتمــاع للدعــارة فــإن العبــارة‬\n      ‫الــواردة يف الشــهادة هــي (وأفــادوا بأنهــم مارســوا الفاحشــة جميعــا ‪)...‬‬\n      ‫ولــم تكــن العبــارة (أفادتــا) خاصــة باملرأتــن وقــررت بأنــه لــم يظهــر لهــا‬\n      ‫مــا يوجــب الرجــوع عمــا حكمــت بــه ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                            ‫االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم وتاريــخ ‪1433/08/10‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقم وتاريخ ‪1433/08/10‬هـ ففي يوم األحد املوافق‪1433/10/22‬هـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا قــدم املدعــي العام‪...........‬دعــواه‬\n      ‫ضــد كل مــن ‪ 34، ........... -1-‬ســنه ‪ ،‬نيجيــري اجلنســية مبوجــب‬\n      ‫رخصــة اإلقامــة رقــم( ‪،)...........‬غيــر محصــن‪ ،‬مقيــم مبدينــة الريــاض‪،‬‬\n      ‫صــدر لــه أمــر اإلفــراج رقــم ‪...........‬وتاريــخ ‪1433 /7 / 23‬ه ـ اســتناد ًا‬\n      ‫للمــادة ‪ 120‬مــن نظــام اإلجراءات اجلزائية‪36،...........-2 .‬ســنة‪ ،‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...........‬غيــر محصــن ‪ ،‬مقيــم‬\n\n‫‪279‬‬\n\f‫مبدينــة الريــاض ‪ ،‬صــدر لــه امــر االفــراج ‪...........‬وتاريــخ ‪1433/7/23‬ه ـ‬\n‫استناد ًا للمادة ‪ 120‬من نظام االجراءات اجلزائية ‪28 ........... - 3‬سنة‪،‬‬\n‫نيجيريــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم(‪) ........‬غيــر محصنــة‪،‬‬\n‫مقيمــة مبدينــة الريــاض ‪ ،‬صــدر لهــا امــر االفــراج رقم‪...........‬وتاريــخ‬\n‫‪1433/7/21‬ه ـ اســتناد ًا للمــادة ‪ 120‬مــن نظــام االجــراءات اجلزائيــة‬\n‫‪28 ........... -4‬ســنة‪ ،‬نيجيريــة اجلنســية مبوجــب االثبــات املؤقــت ‪ ،‬غيــر‬\n‫محصنــة ‪ ،‬مقيمــة مبدينــة الريــاض ‪ ،‬موقوفــة بســجن النســاء مبوجــب‬\n‫أمــر متديــد التوقيــف رقــم ‪ ...........‬وتاريــخ ‪1433/7/23‬ه ـ اســتناد ًا للمادة‬\n‫‪ 121‬مــن نظــام االجــراءات اجلزائيــة الوقائــع ‪ :‬انــه بتاريخ‪1433/7/18‬ه ـ‬\n‫مت القبــض علــى املذكوريــن مــن قبــل هيئــة االمــر باملعــروف والنهــي‬\n‫عــن املنكــر إثــر توافــر معلومــات عــن قيــام االول والثانــي بإدخــال‬\n‫امرأتــن إلــى داخــل إحــدى الشــقق وبانتقــال الفرقــة القابضــة للموقــع مت‬\n‫مشــاهدة االول وهــو يخــرج مــن الشــقة وعنــد مشــاهدته للفرقــة ظهــرت‬\n‫عليــه عالمــات االرتبــاك وحــاول رفــع صوتــه لتنبيــه مــن بداخــل الشــقة‬\n‫ومت اســتدعاء الثانــي والــذي خــرج مرتــدي ملالبســه الداخليــة فقــط ومت‬\n‫اســتدعاء الثالثــة والرابعــة وأفــاد املذكوريــن للفرقــة أنهــم مارســوا‬\n‫الفاحشــة وأنها ليســت املرة االولى التي يجتمعون بها وأنهم على موعد‬\n‫مــع الثالثــة والرابعــة لتســليمهما املــال مقابــل ممارســة الفاحشــة وبســماع‬\n‫أقــوال األول واســتجوابه اعتــرف بربطــه العالقــة احملرمــة بالثالثــة وأنــه‬\n‫ســبق أن قــام بــإركاب الفتاتــن برفقــة األول وأنهــا املــرة األولــى التــي‬\n‫يختلــون بهمــا داخــل شــقة ‪ .‬وبســماع أقــوال الثانــي واســتجوابه اعتــرف‬\n‫باختالئــه احملــرم بالثالثــة والرابعــة برفقــة األول داخــل إحــدى الشــقق‬\n‫وأنــه هــو مــن قــام باســتئجار الشــقة وقــام بدفــع مبلــغ الــف ريــال للفتاتــن‪.‬‬\n\n\n                                                                                         ‫‪280‬‬\n\f      ‫وأســفرت اجــراءات التحقيــق عــن اتهــام املذكوريــن باالجتمــاع بإحــدى‬\n      ‫الشــقق املفروشــة لغــرض الفســاد ودفــع الثانــي مبلــغ مالــي لذلــك‬\n                         ‫واســتئجاره الشــقة ‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n      ‫‪ -1‬مــا جــاء يف أقــوال األول والثانــي املدونــة علــى الصفحــة رقــم (‪)4-1‬‬\n                                                              ‫مــن دفتــر التحقيــق املرفــق‬\n      ‫‪ -2‬مــا جــاء يف أقــوال الثالثــة والرابعــة املدونــة علــى الصفحــة رقــم (‪)4-1‬‬\n                                                               ‫مــن دفتــر التحقيــق املرفــق‬\n                                             ‫‪ -3‬ما جاء يف محضر القبض املرفق لفه‬\n      ‫وبالبحــث بســجلهم اجلنائــي لــم يعثــر لهمــا علــى أي ســابقة مســجلة حتــى‬\n      ‫تاريخــه‪ ،‬وحيــث إن مــا أقــدم عليــه املذكــورون فعــل محــرم ومعاقــب‬\n      ‫عليــه شــرع ًا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة‬\n                                                       ‫تعزيزيــه لقــاء مــا أســند إليهــم ‪.‬‬\n      ‫وبتالوة الئحة الدعوى على املدعى عليهما األول ‪...........‬والثاني ‪...........‬‬\n      ‫ا ‪ /‬مــا ذكــره املدعــي العــام مــن‬   ‫أجــاب كل واحــد منهمــا مبفــرده قائـ ً‬\n      ‫زمــان ومــكان القبــض واالجتمــاع يف الشــقة مــع املرأتني املدعــى عليهما‬\n      ‫لغــرض الفســاد فصحيــح وأمــا فعــل الفاحشــة فلم يحصل منــا أبد ًا كما‬\n      ‫أقــر املدعــى عليــه الثانــي ‪...........‬بقيامــه بدفــع أجــار الشــقة هكــذا‬\n      ‫أجــاب فطلبــت مــن املدعــي العــام أعضــاء الهيئــة الفرقــة القابضــة البينــة‬\n      ‫وألجــل ذلــك رفعــت اجللســة إلــى يــوم األحــد املوافــق ‪1433/10/29‬ه ـ‬\n      ‫الســاعة العاشــرة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                            ‫وعلــى الــه وصحبــه أجمعــن حــرر يف ‪1433/10/22‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي املتــدرب باحملكمــة‬\n      ‫اجلزائيــة واملكلــف بنظــر هــذه القضيــة مــن قبــل فضيلــة الشــيخ‬\n\n\n‫‪281‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":276,"source_page_end":281,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"36a7b8b1a86f1f9e11aaab41886ddadf075e167288917ce18a846a270dce4d5a","normalized_text_hash":"08bfe02dbda3a5678f51af9cf4d8713fdb80220e687ce5b3e33cc36314bb40bf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p276-3445972"}]$archive_payload$::jsonb) AS x LIMIT 25
